import React, { useState, useEffect } from 'react'
import { useNavigate } from 'react-router-dom'
import {
  DataGrid,
  GridColDef,
  GridPaginationModel,
  GridRowId,
  GridRenderCellParams
} from '@mui/x-data-grid'
import {
  Tooltip,
  IconButton,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  Button,
  CircularProgress,
  Stack,
  Box,
  Chip,
  Typography
} from '@mui/material'
import {
  Visibility as ViewIcon,
  Cancel as CancelIcon,
  QrCode2 as QrCodeIcon,
  FactCheck as HandoverIcon,
  ReceiptLong as InvoiceIcon,
  LocationOn as LocationIcon
} from '@mui/icons-material'
import { format } from 'date-fns'
import { getDateLocale } from '@/utils/dateLocale'
import * as bookcarsTypes from ':bookcars-types'
import * as bookcarsHelper from ':bookcars-helper'
import * as BookingService from '@/services/BookingService'
import * as PaymentService from '@/services/PaymentService'
import * as helper from '@/utils/helper'
import { strings } from '@/lang/booking-list'
import { strings as commonStrings } from '@/lang/common'
import env from '@/config/env.config'
import BookingStatus from '@/components/BookingStatus'
import Extras from '@/components/Extras'

import '@/assets/css/booking-list.css'

interface BookingListProps {
  suppliers?: string[]
  statuses?: string[]
  filter?: bookcarsTypes.Filter | null
  car?: string
  user?: bookcarsTypes.User
  hideDates?: boolean
  hideCarColumn?: boolean
  hideSupplierColumn?: boolean
  language?: string
  loading?: boolean
  checkboxSelection?: boolean
  onLoad?: bookcarsTypes.DataEvent<bookcarsTypes.Booking>
}

const BookingList = ({
  suppliers: bookingSuppliers,
  statuses: bookingStatuses,
  filter: bookingFilter,
  car: bookingCar,
  user: bookingUser,
  hideDates,
  hideCarColumn,
  hideSupplierColumn,
  language,
  checkboxSelection,
  onLoad,
}: BookingListProps) => {
  const navigate = useNavigate()

  const [user, setUser] = useState<bookcarsTypes.User>()
  const [page, setPage] = useState(0)
  const [pageSize, setPageSize] = useState(env.isMobile ? env.BOOKINGS_MOBILE_PAGE_SIZE : env.BOOKINGS_PAGE_SIZE)
  const [columns, setColumns] = useState<GridColDef<bookcarsTypes.Booking>[]>([])
  const [rows, setRows] = useState<bookcarsTypes.Booking[]>([])
  const [rowCount, setRowCount] = useState(0)
  const [fetch, setFetch] = useState(false)
  const [selectedId, setSelectedId] = useState('')
  const [suppliers, setSuppliers] = useState<string[] | undefined>(bookingSuppliers)
  const [statuses, setStatuses] = useState<string[] | undefined>(bookingStatuses)
  const [filter, setFilter] = useState<bookcarsTypes.Filter | undefined | null>(bookingFilter)
  const [car, setCar] = useState<string>(bookingCar || '')
  const [paginationModel, setPaginationModel] = useState<GridPaginationModel>({
    pageSize: env.BOOKINGS_PAGE_SIZE,
    page: 0,
  })
  const [loading, setLoading] = useState(true)
  const [openCancelDialog, setOpenCancelDialog] = useState(false)
  const [cancelRequestSent, setCancelRequestSent] = useState(false)
  const [cancelRequestProcessing, setCancelRequestProcessing] = useState(false)

  useEffect(() => {
    if (!env.isMobile) {
      setPage(paginationModel.page)
      setPageSize(paginationModel.pageSize)
    }
  }, [paginationModel])

  const fetchData = async (_page: number, _user?: bookcarsTypes.User, _car?: string) => {
    try {
      const _pageSize = env.isMobile ? env.BOOKINGS_MOBILE_PAGE_SIZE : pageSize

      if (suppliers && statuses) {
        setLoading(true)

        const payload: bookcarsTypes.GetBookingsPayload = {
          suppliers,
          statuses,
          filter: filter || undefined,
          car: _car || car,
          user: (_user && _user._id) || undefined,
        }

        const data = await BookingService.getBookings(
          payload,
          _page + 1,
          _pageSize,
        )
        const _data = data && data.length > 0 ? data[0] : { pageInfo: { totalRecord: 0 }, resultData: [] }
        if (!_data) {
          helper.error()
          return
        }
        const totalRecords = Array.isArray(_data.pageInfo) && _data.pageInfo.length > 0 ? _data.pageInfo[0].totalRecords : 0

        for (const booking of _data.resultData) {
          booking.price = await PaymentService.convertPrice(booking.price!)
        }

        if (env.isMobile) {
          const _rows = _page === 0 ? _data.resultData : [...rows, ..._data.resultData]
          setRows(_rows)
          setRowCount(totalRecords)
          setFetch(_data.resultData.length > 0)
          if (onLoad) {
            onLoad({ rows: _data.resultData, rowCount: totalRecords })
          }
        } else {
          setRows(_data.resultData)
          setRowCount(totalRecords)
          if (onLoad) {
            onLoad({ rows: _data.resultData, rowCount: totalRecords })
          }
        }
      } else {
        setRows([])
        setRowCount(0)
        if (onLoad) {
          onLoad({ rows: [], rowCount: 0 })
        }
      }
    } catch (err) {
      helper.error(err)
    } finally {
      setLoading(false)
    }
  }

  useEffect(() => {
    setSuppliers(bookingSuppliers)
  }, [bookingSuppliers])

  useEffect(() => {
    setStatuses(bookingStatuses)
  }, [bookingStatuses])

  useEffect(() => {
    setFilter(bookingFilter)
  }, [bookingFilter])

  useEffect(() => {
    setCar(bookingCar || '')

    if (bookingCar) {
      fetchData(page, user, bookingCar)
    }
  }, [bookingCar]) // eslint-disable-line react-hooks/exhaustive-deps

  useEffect(() => {
    setUser(bookingUser)

    if (bookingUser) {
      fetchData(page, bookingUser, car)
    }
  }, [bookingUser]) // eslint-disable-line react-hooks/exhaustive-deps

  useEffect(() => {
    if (suppliers && statuses && user) {
      fetchData(page, user)
    }
  }, [page]) // eslint-disable-line react-hooks/exhaustive-deps

  useEffect(() => {
    if (suppliers && statuses && user) {
      if (page === 0) {
        fetchData(0, user)
      } else {
        const _paginationModel = bookcarsHelper.clone(paginationModel)
        _paginationModel.page = 0
        setPaginationModel(_paginationModel)
      }
    }
  }, [pageSize]) // eslint-disable-line react-hooks/exhaustive-deps

  const getDate = (date?: string) => {
    if (!date) {
      return '—'
    }

    const d = new Date(date)
    if (Number.isNaN(d.getTime())) {
      return '—'
    }

    return `${bookcarsHelper.formatDatePart(d.getDate())}-${bookcarsHelper.formatDatePart(d.getMonth() + 1)}-${d.getFullYear()}`
  }

  const getColumns = (): GridColDef<bookcarsTypes.Booking>[] => {
    const _columns: GridColDef<bookcarsTypes.Booking>[] = [
      {
        field: 'from',
        headerName: commonStrings.FROM,
        flex: 1,
        valueGetter: (value: string) => getDate(value),
      },
      {
        field: 'to',
        headerName: commonStrings.TO,
        flex: 1,
        valueGetter: (value: string) => getDate(value),
      },
      {
        field: 'price',
        headerName: strings.PRICE,
        flex: 1.2,
        renderCell: ({ row, value }: GridRenderCellParams<bookcarsTypes.Booking, string>) => {
          const isPaid = row.status === bookcarsTypes.BookingStatus.Paid || row.status === bookcarsTypes.BookingStatus.PaidInFull
          const isDeposit = row.status === bookcarsTypes.BookingStatus.Deposit
          const isCancelled = row.status === bookcarsTypes.BookingStatus.Cancelled
          return (
            <Box sx={{ display: 'flex', flexDirection: 'column', gap: 0.3, py: 0.5 }}>
              <span className="bp" style={{ fontFamily: 'var(--sr-font-mono, monospace)', fontWeight: 800, fontSize: 13 }}>
                {value}
              </span>
              <Chip
                size="small"
                label={isCancelled ? 'Cancelled' : isPaid ? 'Payment recorded' : isDeposit ? 'Deposit recorded' : 'Payment pending'}
                sx={{
                  height: 18,
                  fontSize: 9,
                  fontWeight: 700,
                  bgcolor: (isPaid || isDeposit) ? 'rgba(5, 150, 105, 0.12)' : isCancelled ? 'rgba(0,0,0,0.06)' : 'rgba(217, 119, 6, 0.12)',
                  color: (isPaid || isDeposit) ? 'var(--sr-emerald)' : isCancelled ? 'text.secondary' : 'var(--sr-accent-text)',
                  fontFamily: 'var(--sr-font-mono, monospace)',
                  alignSelf: 'flex-start'
                }}
              />
            </Box>
          )
        },
        valueGetter: (value: number) => bookcarsHelper.formatPrice(value, commonStrings.CURRENCY, language as string),
      },
      {
        field: 'status',
        headerName: strings.STATUS,
        flex: 1,
        renderCell: ({ value }: GridRenderCellParams<bookcarsTypes.Booking, bookcarsTypes.BookingStatus>) => <BookingStatus value={value!} showIcon />,
        valueGetter: (value: string) => value,
      },
      {
        field: 'action',
        headerName: '',
        sortable: false,
        disableColumnMenu: true,
        flex: 1.2,
        renderCell: ({ row }: GridRenderCellParams<bookcarsTypes.Booking>) => {
          const cancelBooking = (e: React.MouseEvent<HTMLElement>) => {
            e.stopPropagation() // don't select this row after clicking
            setSelectedId(row._id || '')
            setOpenCancelDialog(true)
          }

          const today = new Date()
          today.setHours(0)
          today.setMinutes(0)
          today.setSeconds(0)
          today.setMilliseconds(0)

          return (
            <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
              <Button
                size="small"
                variant="outlined"
                startIcon={<QrCodeIcon sx={{ fontSize: '14px !important' }} />}
                onClick={() => navigate(`/booking?b=${row._id}`)}
                sx={{
                  borderColor: 'rgba(5, 150, 105, 0.35)',
                  color: 'var(--sr-emerald)',
                  fontSize: 11,
                  fontWeight: 700,
                  textTransform: 'none',
                  borderRadius: '6px',
                  py: 0.3,
                  px: 1,
                  height: 28,
                  '&:hover': { bgcolor: 'rgba(5, 150, 105, 0.08)', borderColor: '#059669' }
                }}
              >
                QR Pass
              </Button>
              {row.cancellation
                && !row.cancelRequest
                && row.status !== bookcarsTypes.BookingStatus.Cancelled
                && new Date(row.from) >= today && (
                  <Tooltip title={strings.CANCEL}>
                    <IconButton size="small" onClick={cancelBooking} sx={{ color: '#DC2626' }}>
                      <CancelIcon fontSize="small" />
                    </IconButton>
                  </Tooltip>
                )}
            </Box>
          )
        },
      },
    ]

    if (hideDates) {
      _columns.splice(0, 2)
    }

    if (!hideCarColumn) {
      _columns.unshift({
        field: 'car',
        headerName: strings.CAR,
        flex: 1.5,
        renderCell: ({ row }: GridRenderCellParams<bookcarsTypes.Booking>) => {
          const c = row.car as bookcarsTypes.Car | undefined
          const imgUrl = c?.image ? bookcarsHelper.joinURL(env.CDN_CARS, c.image) : undefined
          return (
            <Box sx={{ display: 'flex', alignItems: 'center', gap: 1.5, py: 0.5 }}>
              {imgUrl ? (
                <img
                  src={imgUrl}
                  alt={c?.name || ''}
                  style={{ width: 48, height: 32, objectFit: 'cover', borderRadius: 4, aspectRatio: '16/10' }}
                />
              ) : (
                <Box sx={{ width: 48, height: 32, bgcolor: '#0B1120', borderRadius: 1, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                  <span style={{ fontSize: 9, color: 'var(--sr-emerald)', fontWeight: 800 }}>SR</span>
                </Box>
              )}
              <Box sx={{ minWidth: 0 }}>
                <Typography sx={{ fontWeight: 700, fontSize: 13, color: 'var(--sr-text, #0F172A)' }} noWrap>
                  {c?.name || '—'}
                </Typography>
                {(row.pickupLocation as bookcarsTypes.Location | undefined)?.name && (
                  <Typography variant="caption" sx={{ color: 'text.secondary', display: 'flex', alignItems: 'center', gap: 0.3 }} noWrap>
                    📍 {(row.pickupLocation as bookcarsTypes.Location).name}
                  </Typography>
                )}
              </Box>
            </Box>
          )
        },
        valueGetter: (value: bookcarsTypes.Car) => value?.name,
      })
    }

    if (!hideSupplierColumn) {
      _columns.unshift({
        field: 'supplier',
        headerName: commonStrings.SUPPLIER,
        flex: 1,
        renderCell: ({ row, value }: GridRenderCellParams<bookcarsTypes.Booking, string>) => (
          <div className="cell-supplier">
            {(row.supplier as bookcarsTypes.User | undefined)?.avatar && <img src={bookcarsHelper.joinURL(env.CDN_USERS, (row.supplier as bookcarsTypes.User).avatar)} alt={value || ''} />}
          </div>
        ),
        valueGetter: (value: bookcarsTypes.User) => value?.fullName,
      })
    }

    return _columns
  }

  useEffect(() => {
    if (suppliers && statuses && user) {
      const _columns = getColumns()
      setColumns(_columns)

      if (page === 0) {
        fetchData(0, user)
      } else {
        const _paginationModel = bookcarsHelper.clone(paginationModel)
        _paginationModel.page = 0
        setPaginationModel(_paginationModel)
      }
    }
  }, [suppliers, statuses, filter]) // eslint-disable-line react-hooks/exhaustive-deps

  useEffect(() => {
    if (env.isMobile) {
      const element = document.querySelector('body')

      if (element) {
        element.onscroll = () => {
          if (fetch
            && !loading
            && window.scrollY > 0
            && window.scrollY + window.innerHeight + env.INFINITE_SCROLL_OFFSET >= document.body.scrollHeight) {
            setLoading(true)
            setPage(page + 1)
          }
        }
      }
    }
  }, [page, fetch, loading])

  const handleCloseCancelBooking = () => {
    setOpenCancelDialog(false)
    if (cancelRequestSent) {
      setTimeout(() => {
        setCancelRequestSent(false)
      }, 500)
    }
  }

  const handleConfirmCancelBooking = async () => {
    try {
      setCancelRequestProcessing(true)
      const status = await BookingService.cancel(selectedId)
      if (status === 200) {
        const row = rows.find((r) => r._id === selectedId)
        if (row) {
          row.cancelRequest = true
          row.status = bookcarsTypes.BookingStatus.Cancelled
          row.lifecycleStatus = 'CANCELLED'

          setCancelRequestSent(true)
          setRows([...rows])
          setSelectedId('')
          setCancelRequestProcessing(false)
        } else {
          helper.error()
        }
      } else {
        helper.error()
        setOpenCancelDialog(false)
        setCancelRequestProcessing(false)
      }
    } catch (err) {
      helper.error(err)
      setOpenCancelDialog(false)
      setCancelRequestProcessing(false)
    }
  }

  const _locale = getDateLocale(language)
  const _format = ({
    fr: 'eee d LLL yyyy kk:mm',
    de: 'eee d LLL yyyy kk:mm',
    pt: 'eee d LLL yyyy kk:mm',
    it: 'eee d LLL yyyy kk:mm',
    zh: 'yyyy年M月d日 eee HH:mm',
    ja: 'yyyy年M月d日 eee HH:mm',
  } as Record<string, string>)[language ?? ''] || 'eee, d LLL yyyy, p'
  const bookingDetailHeight = env.SUPPLIER_IMAGE_HEIGHT + 10

  return (
    <div className="bs-list">
      {user
        && (env.isMobile ? (
          <>
            {rows.map((booking) => {
              const _bookingCar = booking.car as bookcarsTypes.Car | undefined
              const bookingSupplier = booking.supplier as bookcarsTypes.User | undefined
              const from = new Date(booking.from)
              const to = new Date(booking.to)
              const days = bookcarsHelper.days(from, to)
              const bookingStatus = booking.status || bookcarsTypes.BookingStatus.Pending

              const isPaid = bookingStatus === bookcarsTypes.BookingStatus.Paid || bookingStatus === bookcarsTypes.BookingStatus.PaidInFull
              const isDeposit = bookingStatus === bookcarsTypes.BookingStatus.Deposit
              const isCancelled = bookingStatus === bookcarsTypes.BookingStatus.Cancelled
              const carImg = _bookingCar?.image ? bookcarsHelper.joinURL(env.CDN_CARS, _bookingCar.image) : undefined

              return (
                <div key={booking._id} className="booking-details" style={{ borderRadius: '16px', overflow: 'hidden', border: '1px solid var(--sr-border, #E2E8F0)', background: 'var(--sr-surface, #FFFFFF)', marginBottom: '16px' }}>
                  {carImg && (
                    <div style={{ width: '100%', height: '140px', overflow: 'hidden', background: '#0B1120' }}>
                      <img src={carImg} alt={_bookingCar?.name || ''} style={{ width: '100%', height: '100%', objectFit: 'cover' }} />
                    </div>
                  )}

                  <Box sx={{ p: 2, display: 'flex', justifyContent: 'space-between', alignItems: 'center', flexWrap: 'wrap', gap: 1 }}>
                    <div className={`bs bs-${String(bookingStatus).toLowerCase()}`} style={{ margin: 0 }}>
                      <span>{helper.getBookingStatus(bookingStatus)}</span>
                    </div>
                    <Chip
                      size="small"
                      label={isCancelled ? 'Cancelled · refund not confirmed' : isPaid ? 'Payment recorded' : isDeposit ? 'Deposit recorded' : 'Payment pending'}
                      sx={{
                        fontSize: 10,
                        fontWeight: 700,
                        fontFamily: 'var(--sr-font-mono, monospace)',
                        bgcolor: (isPaid || isDeposit) ? 'rgba(5, 150, 105, 0.12)' : isCancelled ? 'rgba(0,0,0,0.06)' : 'rgba(217, 119, 6, 0.12)',
                        color: (isPaid || isDeposit) ? 'var(--sr-emerald)' : isCancelled ? 'text.secondary' : 'var(--sr-accent-text)'
                      }}
                    />
                  </Box>

                  <div className="booking-detail" style={{ height: bookingDetailHeight }}>
                    <span className="booking-detail-title">{strings.CAR}</span>
                    <div className="booking-detail-value" style={{ fontWeight: 800 }}>{_bookingCar?.name || '—'}</div>
                  </div>
                  <div className="booking-detail" style={{ height: bookingDetailHeight }}>
                    <span className="booking-detail-title">{strings.DAYS}</span>
                    <div className="booking-detail-value">
                      {`${helper.getDaysShort(language as string, bookcarsHelper.days(from, to))} (${bookcarsHelper.capitalize(
                        format(from, _format, { locale: _locale }),
                      )} - ${bookcarsHelper.capitalize(format(to, _format, { locale: _locale }))})`}
                    </div>
                  </div>
                  <div className="booking-detail" style={{ height: bookingDetailHeight }}>
                    <span className="booking-detail-title">{commonStrings.PICK_UP_LOCATION}</span>
                    <div className="booking-detail-value">📍 {(booking.pickupLocation as bookcarsTypes.Location | undefined)?.name || '—'}</div>
                  </div>
                  <div className="booking-detail" style={{ height: bookingDetailHeight }}>
                    <span className="booking-detail-title">{commonStrings.DROP_OFF_LOCATION}</span>
                    <div className="booking-detail-value">{(booking.dropOffLocation as bookcarsTypes.Location | undefined)?.name || '—'}</div>
                  </div>
                  <div className="booking-detail" style={{ height: bookingDetailHeight }}>
                    <span className="booking-detail-title">{commonStrings.SUPPLIER}</span>
                    <div className="booking-detail-value">
                      <div className="car-supplier">
                        {bookingSupplier?.avatar && env.CDN_USERS && <img src={bookcarsHelper.joinURL(env.CDN_USERS, bookingSupplier.avatar)} alt={bookingSupplier.fullName || ''} />}
                        <span className="car-supplier-name">{bookingSupplier?.fullName || '—'}</span>
                      </div>
                    </div>
                  </div>

                  {(booking.cancellation
                    || booking.amendments
                    || booking.collisionDamageWaiver
                    || booking.theftProtection
                    || booking.fullInsurance
                    || booking.additionalDriver) && (
                      <Extras
                        booking={booking}
                        days={days}
                      />
                    )}
                  <div className="booking-detail" style={{ height: bookingDetailHeight }}>
                    <span className="booking-detail-title">{strings.COST}</span>
                    <div className="booking-detail-value booking-price" style={{ fontFamily: 'var(--sr-font-mono, monospace)', fontWeight: 800 }}>{bookcarsHelper.formatPrice(booking.price as number, commonStrings.CURRENCY, language as string)}</div>
                  </div>

                  <Box sx={{ p: 2, display: 'flex', gap: 1, flexWrap: 'wrap' }}>
                    <Button
                      variant="contained"
                      size="small"
                      startIcon={<QrCodeIcon />}
                      onClick={() => navigate(`/booking?b=${booking._id}`)}
                      sx={{
                        flexGrow: 1,
                        bgcolor: '#107487',
                        '&:hover': { bgcolor: '#047857' },
                        fontWeight: 700,
                        fontSize: 12,
                        textTransform: 'none',
                        borderRadius: '8px',
                        py: 0.8
                      }}
                    >
                      View QR Trip Pass
                    </Button>
                    <Button
                      variant="outlined"
                      size="small"
                      startIcon={<HandoverIcon />}
                      onClick={() => navigate(`/booking?b=${booking._id}#handover`)}
                      sx={{
                        borderColor: 'rgba(5, 150, 105, 0.4)',
                        color: 'var(--sr-emerald)',
                        fontWeight: 700,
                        fontSize: 12,
                        textTransform: 'none',
                        borderRadius: '8px'
                      }}
                    >
                      6-Pt Handover
                    </Button>
                    {booking.cancellation
                      && !booking.cancelRequest
                      && booking.status !== bookcarsTypes.BookingStatus.Cancelled
                      && new Date(booking.from) > new Date() && (
                        <Button
                          variant="outlined"
                          color="error"
                          size="small"
                          onClick={() => {
                            setSelectedId(booking._id as string)
                            setOpenCancelDialog(true)
                          }}
                          sx={{ textTransform: 'none', borderRadius: '8px' }}
                        >
                          {strings.CANCEL}
                        </Button>
                      )}
                  </Box>
                </div>
              )
            })}
          </>
        ) : (
          <DataGrid
            className="data-grid"
            checkboxSelection={checkboxSelection}
            getRowId={(row: bookcarsTypes.Booking): GridRowId => row._id as GridRowId}
            columns={columns}
            rows={rows}
            rowCount={rowCount}
            loading={loading}
            initialState={{
              pagination: {
                paginationModel: { pageSize: env.BOOKINGS_PAGE_SIZE },
              },
            }}
            pageSizeOptions={[env.BOOKINGS_PAGE_SIZE, 50, 100]}
            paginationMode="server"
            paginationModel={paginationModel}
            onPaginationModelChange={setPaginationModel}
            disableRowSelectionOnClick
          />
        ))}

      <Dialog disableEscapeKeyDown maxWidth="xs" open={openCancelDialog}>
        <DialogTitle className="dialog-header">{!cancelRequestSent && !cancelRequestProcessing && commonStrings.CONFIRM_TITLE}</DialogTitle>
        <DialogContent className="dialog-content">
          {cancelRequestProcessing ? (
            <Stack sx={{ color: '#232323' }}>
              <CircularProgress color="inherit" />
            </Stack>
          ) : cancelRequestSent ? (
            strings.CANCEL_BOOKING_REQUEST_SENT
          ) : (
            strings.CANCEL_BOOKING
          )}
        </DialogContent>
        <DialogActions className="dialog-actions">
          {!cancelRequestProcessing && (
            <Button onClick={handleCloseCancelBooking} variant="outlined" color="primary" className="btn-secondary">
              {commonStrings.CLOSE}
            </Button>
          )}
          {!cancelRequestSent && !cancelRequestProcessing && (
            <Button onClick={handleConfirmCancelBooking} variant="contained" className="btn-primary">
              {commonStrings.CONFIRM}
            </Button>
          )}
        </DialogActions>
      </Dialog>
    </div>
  )
}

export default BookingList

import React, { useState, useEffect } from 'react'
import { useNavigate } from 'react-router-dom'
import {
  Button,
  Tooltip,
  Accordion,
  AccordionSummary,
  AccordionDetails,
} from '@mui/material'
import {
  LocalGasStation as CarTypeIcon,
  AccountTree as GearboxIcon,
  Person as SeatsIcon,
  AcUnit as AirconIcon,
  DirectionsCar as MileageIcon,
  Check as CheckIcon,
  Clear as UncheckIcon,
  Info as InfoIcon,
  LocationOn as LocationIcon,
  ExpandMore as ExpandMoreIcon,
  Verified as VerifiedIcon,
  Terrain as TerrainIcon,
} from '@mui/icons-material'
import * as bookcarsTypes from ':bookcars-types'
import * as bookcarsHelper from ':bookcars-helper'
import env from '@/config/env.config'
import * as helper from '@/utils/helper'
import { strings as commonStrings } from '@/lang/common'
import { strings } from '@/lang/cars'
import Badge from '@/components/Badge'
import * as UserService from '@/services/UserService'
import * as PaymentService from '@/services/PaymentService'

import DoorsIcon from '@/assets/img/car-door.png'
import DistanceIcon from '@/assets/img/distance-icon.png'
import RatingIcon from '@/assets/img/rating-icon.png'
import CO2MinIcon from '@/assets/img/co2-min-icon.png'
import CO2MiddleIcon from '@/assets/img/co2-middle-icon.png'
import CO2MaxIcon from '@/assets/img/co2-max-icon.png'

import '@/assets/css/car.css'

interface CarProps {
  car: bookcarsTypes.Car
  rentalMode?: bookcarsTypes.RentalMode
  booking?: bookcarsTypes.Booking
  pickupLocation?: string
  dropOffLocation?: string
  from: Date
  to: Date
  pickupLocationName?: string
  distance?: string
  hideSupplier?: boolean
  sizeAuto?: boolean
  hidePrice?: boolean
}

const Car = ({
  car,
  booking,
  rentalMode,
  pickupLocation,
  dropOffLocation,
  from,
  to,
  pickupLocationName,
  distance,
  hideSupplier,
  sizeAuto,
  hidePrice,
}: CarProps) => {
  const navigate = useNavigate()

  const [language, setLanguage] = useState('')
  const [days, setDays] = useState(0)
  const [totalPrice, setTotalPrice] = useState(0)
  const [deposit, setDeposit] = useState(0)
  const [cancellation, setCancellation] = useState('')
  const [amendments, setAmendments] = useState('')
  const [theftProtection, setTheftProtection] = useState('')
  const [collisionDamageWaiver, setCollisionDamageWaiver] = useState('')
  const [fullInsurance, setFullInsurance] = useState('')
  const [additionalDriver, setAdditionalDriver] = useState('')
  const [loading, setLoading] = useState(true)
  const [imageUnavailable, setImageUnavailable] = useState(false)

  useEffect(() => {
    setLanguage(UserService.getLanguage())
  }, [])

  useEffect(() => {
    const fetchPrice = async () => {
      if (from && to) {
        const _totalPrice = await PaymentService.convertPrice(bookcarsHelper.calculateTotalPrice(car, from as Date, to as Date, car.supplier.priceChangeRate || 0))
        setTotalPrice(_totalPrice)
        setDays(bookcarsHelper.days(from, to))
      }
    }

    fetchPrice()
  }, [from, to]) // eslint-disable-line react-hooks/exhaustive-deps

  useEffect(() => {
    const fetchDeposit = async () => {
      if (car.deposit > 0) {
        const _deposit = await PaymentService.convertPrice(car.deposit)
        setDeposit(_deposit)
      } else {
        setDeposit(0)
      }
    }

    fetchDeposit()
  }, [car.deposit])

  useEffect(() => {
    const init = async () => {
      const priceChangeRate = car.supplier.priceChangeRate || 0
      const _cancellation = (car.cancellation > -1 && (await helper.getCancellation(car.cancellation, language, priceChangeRate))) || ''
      const _amendments = (car.amendments > -1 && (await helper.getAmendments(car.amendments, language, priceChangeRate))) || ''
      const _theftProtection = (car.theftProtection > -1 && (await helper.getTheftProtection(car.theftProtection, language, priceChangeRate))) || ''
      const _collisionDamageWaiver = (car.collisionDamageWaiver > -1 && (await helper.getCollisionDamageWaiver(car.collisionDamageWaiver, language, priceChangeRate))) || ''
      const _fullInsurance = (car.fullInsurance > -1 && (await helper.getFullInsurance(car.fullInsurance, language, priceChangeRate))) || ''
      const _additionalDriver = (car.additionalDriver > -1 && (await helper.getAdditionalDriver(car.additionalDriver, language, priceChangeRate))) || ''

      setCancellation(_cancellation)
      setAmendments(_amendments)
      setTheftProtection(_theftProtection)
      setCollisionDamageWaiver(_collisionDamageWaiver)
      setFullInsurance(_fullInsurance)
      setAdditionalDriver(_additionalDriver)
      setLoading(false)

      if (!hidePrice) {
        let _totalPrice = await PaymentService.convertPrice(bookcarsHelper.calculateTotalPrice(car, from as Date, to as Date, car.supplier.priceChangeRate || 0))
        setTotalPrice(_totalPrice)
      }
    }

    init()
  }, [hidePrice]) // eslint-disable-line react-hooks/exhaustive-deps

  const getExtraIcon = (option: string, extra: number) => {
    let available = false
    if (booking) {
      if (option === 'cancellation' && booking.cancellation && extra > 0) {
        available = true
      }
      if (option === 'amendments' && booking.amendments && extra > 0) {
        available = true
      }
      if (option === 'collisionDamageWaiver' && booking.collisionDamageWaiver && extra > 0) {
        available = true
      }
      if (option === 'theftProtection' && booking.theftProtection && extra > 0) {
        available = true
      }
      if (option === 'fullInsurance' && booking.fullInsurance && extra > 0) {
        available = true
      }
      if (option === 'additionalDriver' && booking.additionalDriver && extra > 0) {
        available = true
      }
    }

    return extra === -1
      ? <UncheckIcon className="unavailable" />
      : extra === 0 || available
        ? <CheckIcon className="available" />
        : <InfoIcon className="extra-info" />
  }

  if (loading || !language || (!hidePrice && (!days || !totalPrice))) {
    return null
  }
  // console.log('car')

  const fr = language === 'fr'
  // Demo and newly onboarded vehicles may not have photos yet. Missing media
  // must never break the whole search results route.
  const carImage = car.image && env.CDN_CARS
    ? bookcarsHelper.joinURL(env.CDN_CARS, car.image)
    : undefined
  const supplierAvatar = car.supplier?.avatar && env.CDN_USERS
    ? bookcarsHelper.joinURL(env.CDN_USERS, car.supplier.avatar)
    : undefined

  return (
    <div key={car._id} className="car-container">
      {pickupLocationName && (
        <div className="car-header">
          <div className="location">
            <LocationIcon />
            <span className="location-name">{pickupLocationName}</span>
          </div>
          {distance && (
            <div className="distance">
              <img alt="Distance" src={DistanceIcon} />
              <Badge backgroundColor="#D8EDF9" color="#000" text={`${distance} ${strings.FROM_YOU}`} />
            </div>
          )}
        </div>
      )}
      <article>
        <div className="car">
          <div className="car-top-badges">
            {(car.selfDriveAvailable || car.withDriverAvailable) && (
              <span className={car.selfDriveAvailable ? 'car-badge badge-self-drive' : 'car-badge badge-chauffeur'}>
                {car.selfDriveAvailable ? 'Self-drive' : 'With chauffeur'}
              </span>
            )}
            {car.terrainCapability === bookcarsTypes.TerrainCapability.NorthernMountains && (
              <span className="car-badge badge-hill-route">
                Hill routes
              </span>
            )}
          </div>
          {imageUnavailable || !carImage
            ? <div className="car-img-unavailable" role="img" aria-label={`${car.name} photo unavailable`}><svg aria-hidden="true" viewBox="0 0 120 72" focusable="false"><path d="m20 45 8-17c2-5 6-8 12-8h38c6 0 10 3 13 8l9 17v11H20V45Z" fill="currentColor" opacity=".16"/><path d="m30 43 7-14c1-3 3-4 6-4h36c3 0 5 1 7 4l7 14H30Z" fill="currentColor" opacity=".3"/><path d="M20 45h80v11H20z" fill="currentColor" opacity=".22"/><circle cx="38" cy="56" r="8" fill="#fff" stroke="currentColor" strokeWidth="4"/><circle cx="82" cy="56" r="8" fill="#fff" stroke="currentColor" strokeWidth="4"/></svg><span>Photo coming soon</span></div>
            : <img src={carImage} alt={car.name} className="car-img" onError={() => setImageUnavailable(true)} />}
          <div className="car-row">
            {!hideSupplier && (
              <div className="car-supplier" style={sizeAuto ? { bottom: 10 } : {}} title={car.supplier.fullName}>
                <span className="car-supplier-logo">
                  {supplierAvatar
                    ? <img src={supplierAvatar} alt={car.supplier?.fullName || 'Rental supplier'} />
                    : <span className="car-supplier-avatar-fallback" aria-hidden="true">{car.supplier?.fullName?.slice(0, 1) || 'S'}</span>}
                </span>
                <span className="car-supplier-info">{car.supplier?.fullName || 'Rental supplier'}</span>
              </div>
            )}
            <div className="car-footer">
              <div className="rating">
                {car.rating && car.rating >= 1 && (
                  <>
                    <span className="value">{car.rating.toFixed(2)}</span>
                    <img alt="Rating" src={RatingIcon} />
                  </>
                )}
                {car.trips >= 10 && <span className="trips">{`(${car.trips} ${strings.TRIPS})`}</span>}
              </div>
              {car.co2 && (
                <div className="co2">
                  <img
                    alt="CO2 Effect"
                    src={
                      car.co2 <= 90
                        ? CO2MinIcon
                        : car.co2 <= 110
                          ? CO2MiddleIcon
                          : CO2MaxIcon
                    }
                  />
                  <span>{strings.CO2}</span>
                </div>
              )}
            </div>
          </div>
        </div>
        <div className="car-info">
          <div className="car-info-header">
            <div className="name">{car.name}</div>
            {car.interCityDeliveryBadge && <div className="sr-delivery-badge">{car.interCityDeliveryBadge}</div>}
            {!hidePrice && (
              <div className="price">
                <span className="price-days">{helper.getDays(language, days)}</span>
                <span className="price-main tabular-nums pkr-price">{bookcarsHelper.formatPrice(totalPrice, commonStrings.CURRENCY, language)}</span>
                <span className="price-day">
                  <span>{`${strings.PRICE_PER_DAY} `}</span>
                  <span className="price-day-value tabular-nums pkr-price">{bookcarsHelper.formatPrice(totalPrice / days, commonStrings.CURRENCY, language)}</span>
                </span>
                {
                  car.comingSoon ? (
                    <span className="coming-soon">{strings.COMING_SOON}</span>
                  ) : car.fullyBooked ? (
                    <span className="fully-booked">{strings.FULLY_BOOKED}</span>
                  ) : null
                }
              </div>
            )}
          </div>

          <ul className="car-info-list car-spec-chips">
            <li className="spec-chip">
              <Tooltip title={helper.getSeatsTooltip(car.seats)} placement="top">
                <div className="car-info-list-item">
                  <SeatsIcon />
                  <span className="car-info-list-text">{car.seats > 0 ? `${car.seats} Seats` : '—'}</span>
                </div>
              </Tooltip>
            </li>
            <li className="spec-chip">
              <Tooltip title={helper.getGearboxTooltip(car.gearbox)} placement="top">
                <div className="car-info-list-item">
                  <GearboxIcon />
                  <span className="car-info-list-text">{helper.getGearboxTypeShort(car.gearbox)}</span>
                </div>
              </Tooltip>
            </li>
            <li className="spec-chip">
              <Tooltip title={helper.getCarTypeTooltip(car.type)} placement="top">
                <div className="car-info-list-item">
                  <CarTypeIcon />
                  <span className="car-info-list-text">{helper.getCarTypeShort(car.type)}</span>
                </div>
              </Tooltip>
            </li>
            <li className="spec-chip">
              <Tooltip title={helper.getMileageTooltip(car.mileage, language)} placement="top">
                <div className="car-info-list-item">
                  <MileageIcon />
                  <span className="car-info-list-text">{car.mileage == null ? '—' : helper.getMileage(car.mileage, language)}</span>
                </div>
              </Tooltip>
            </li>
          </ul>
          {/* <Accordion className="accordion">
            <AccordionSummary className="accordion-summary" expandIcon={<ExpandMoreIcon />}>{strings.DETAILS}</AccordionSummary>
            <AccordionDetails> */}
          <ul className="extras-list">
            {car.cancellation > -1 && (
              <li>
                <Tooltip title={booking ? '' : car.cancellation > -1 ? strings.CANCELLATION_TOOLTIP : cancellation} placement="left">
                  <div className="car-info-list-item">
                    {getExtraIcon('cancellation', car.cancellation)}
                    <span className="car-info-list-text">{cancellation}</span>
                  </div>
                </Tooltip>
              </li>
            )}
            {car.amendments > -1 && (
              <li>
                <Tooltip title={booking ? '' : car.amendments > -1 ? strings.AMENDMENTS_TOOLTIP : amendments} placement="left">
                  <div className="car-info-list-item">
                    {getExtraIcon('amendments', car.amendments)}
                    <span className="car-info-list-text">{amendments}</span>
                  </div>
                </Tooltip>
              </li>
            )}
            {car.theftProtection > -1 && (
              <li>
                <Tooltip title={booking ? '' : car.theftProtection > -1 ? strings.THEFT_PROTECTION_TOOLTIP : theftProtection} placement="left">
                  <div className="car-info-list-item">
                    {getExtraIcon('theftProtection', car.theftProtection)}
                    <span className="car-info-list-text">{theftProtection}</span>
                  </div>
                </Tooltip>
              </li>
            )}
            {car.collisionDamageWaiver > -1 && (
              <li>
                <Tooltip
                  title={booking ? '' : car.collisionDamageWaiver > -1 ? strings.COLLISION_DAMAGE_WAVER_TOOLTIP : collisionDamageWaiver}
                  placement="left"
                >
                  <div className="car-info-list-item">
                    {getExtraIcon('collisionDamageWaiver', car.collisionDamageWaiver)}
                    <span className="car-info-list-text">{collisionDamageWaiver}</span>
                  </div>
                </Tooltip>
              </li>
            )}
            {car.fullInsurance > -1 && (
              <li>
                <Tooltip title={booking ? '' : car.fullInsurance > -1 ? strings.FULL_INSURANCE_TOOLTIP : fullInsurance} placement="left">
                  <div className="car-info-list-item">
                    {getExtraIcon('fullInsurance', car.fullInsurance)}
                    <span className="car-info-list-text">{fullInsurance}</span>
                  </div>
                </Tooltip>
              </li>
            )}
            {car.additionalDriver > -1 && (
              <li>
                <Tooltip title={booking ? '' : additionalDriver} placement="left">
                  <div className="car-info-list-item">
                    {getExtraIcon('additionalDriver', car.additionalDriver)}
                    <span className="car-info-list-text">{additionalDriver}</span>
                  </div>
                </Tooltip>
              </li>
            )}
            {car.deposit > 0 && (
              <li>
                <div className="car-info-list-item">
                  <InfoIcon className="extra-info" />
                  <span className="car-info-list-text">{`${strings.DEPOSIT}: ${bookcarsHelper.formatPrice(deposit, commonStrings.CURRENCY, language)}`}</span>
                </div>
              </li>
            )}
          </ul>
          {/* </AccordionDetails>
          </Accordion> */}

          {!hidePrice && (
            <div className="action">
              {
                car.available && !car.comingSoon && !car.fullyBooked && (
                  <Button
                    variant="contained"
                    className="btn-primary btn-book btn-margin-bottom"
                    onClick={() => {
                      navigate('/checkout', {
                        state: {
                          carId: car._id,
                          rentalMode,
                          pickupLocationId: pickupLocation,
                          dropOffLocationId: dropOffLocation,
                          from,
                          to
                        }
                      })
                    }}
                  >
                    {strings.BOOK}
                  </Button>
                )
              }
            </div>
          )}
        </div>

      </article>
    </div>
  )
}

export default Car

import React, { useState, useEffect } from 'react'
import { addDays, format } from 'date-fns'
import {
  Card,
  CardContent,
  Typography
} from '@mui/material'
import * as bookcarsTypes from ':bookcars-types'
import Const from '@/config/const'
import env from '@/config/env.config'
import * as helper from '@/utils/helper'
import { strings } from '@/lang/cars'
import * as CarService from '@/services/CarService'
import Pager from '@/components/Pager'
import Car from '@/components/Car'
import Progress from '@/components/Progress'

import '@/assets/css/car-list.css'

interface CarListProps {
  from?: Date
  to?: Date
  suppliers?: string[]
  pickupLocation?: string
  pickupCoordinates?: { latitude: number; longitude: number }
  dropOffLocation?: string
  pickupLocationName?: string
  carSpecs?: bookcarsTypes.CarSpecs
  carType?: string[]
  gearbox?: string[]
  mileage?: string[]
  fuelPolicy?: string[]
  deposit?: number
  cars?: bookcarsTypes.Car[]
  reload?: boolean
  booking?: bookcarsTypes.Booking
  className?: string
  hidePrice?: boolean
  hideSupplier?: boolean
  loading?: boolean
  sizeAuto?: boolean
  ranges?: string[]
  multimedia?: string[]
  rating?: number
  seats?: number
  distance?: string
  includeAlreadyBookedCars?: boolean
  includeComingSoonCars?: boolean
  onLoad?: bookcarsTypes.DataEvent<bookcarsTypes.Car>
  onDateChange?: (newFrom: Date, newTo: Date) => void
  rentalMode?: bookcarsTypes.RentalMode
  nearbyHubs?: bookcarsTypes.Location[]
  onHubChange?: (hub: bookcarsTypes.Location) => void
}

const CarList = ({
  from,
  to,
  suppliers,
  pickupLocation,
  pickupCoordinates,
  dropOffLocation,
  pickupLocationName,
  carSpecs,
  carType: _carType,
  gearbox,
  mileage,
  fuelPolicy,
  deposit,
  cars,
  reload,
  booking,
  className,
  hidePrice,
  hideSupplier,
  loading: carListLoading,
  sizeAuto,
  ranges,
  multimedia,
  rating,
  seats,
  distance,
  includeAlreadyBookedCars,
  includeComingSoonCars,
  onLoad,
  onDateChange,
  rentalMode,
  nearbyHubs = [],
  onHubChange,
}: CarListProps) => {
  const [init, setInit] = useState(true)
  const [loading, setLoading] = useState(false)
  const [fetch, setFetch] = useState(false)
  const [rows, setRows] = useState<bookcarsTypes.Car[]>([])
  const [rowCount, setRowCount] = useState(0)
  const [totalRecords, setTotalRecords] = useState(0)
  const [page, setPage] = useState(1)

  useEffect(() => {
    if (env.PAGINATION_MODE === Const.PAGINATION_MODE.INFINITE_SCROLL || env.isMobile) {
      const element = document.querySelector('body')

      if (element) {
        element.onscroll = () => {
          if (fetch
            && !loading
            && window.scrollY > 0
            && window.scrollY + window.innerHeight + env.INFINITE_SCROLL_OFFSET >= document.body.scrollHeight) {
            setLoading(true)
            setPage(page + 1)
          }
        }
      }
    }
  }, [fetch, loading, page])

  const fetchData = async (
    _page: number,
    _suppliers?: string[],
    _pickupLocation?: string,
    _carSpecs?: bookcarsTypes.CarSpecs,
    __carType?: string[],
    _gearbox?: string[],
    _mileage?: string[],
    _fuelPolicy?: string[],
    _deposit?: number,
    _ranges?: string[],
    _multimedia?: string[],
    _rating?: number,
    _seats?: number,
  ) => {
    try {
      setLoading(true)

      const payload: bookcarsTypes.GetCarsPayload = {
        suppliers: _suppliers ?? [],
        rentalMode,
        pickupLocation: _pickupLocation,
        pickupLatitude: pickupCoordinates?.latitude,
        pickupLongitude: pickupCoordinates?.longitude,
        carSpecs: _carSpecs,
        carType: __carType,
        gearbox: _gearbox,
        mileage: _mileage,
        fuelPolicy: _fuelPolicy,
        deposit: _deposit,
        ranges: _ranges,
        multimedia: _multimedia,
        rating: _rating,
        seats: _seats,
        from,
        to,
        includeAlreadyBookedCars,
        includeComingSoonCars,
      }

      const data = await CarService.getCars(payload, _page, env.CARS_PAGE_SIZE)

      const _data = data && data.length > 0 ? data[0] : { pageInfo: { totalRecord: 0 }, resultData: [] }
      if (!_data) {
        helper.error()
        return
      }
      const _totalRecords = Array.isArray(_data.pageInfo) && _data.pageInfo.length > 0 ? _data.pageInfo[0].totalRecords : 0

      let _rows = []
      if (env.PAGINATION_MODE === Const.PAGINATION_MODE.INFINITE_SCROLL || env.isMobile) {
        _rows = _page === 1 ? _data.resultData : [...rows, ..._data.resultData]
      } else {
        _rows = _data.resultData
      }

      setRows(_rows)
      setRowCount((_page - 1) * env.CARS_PAGE_SIZE + _rows.length)
      setTotalRecords(_totalRecords)
      setFetch(_data.resultData.length > 0)

      if (((env.PAGINATION_MODE === Const.PAGINATION_MODE.INFINITE_SCROLL || env.isMobile) && _page === 1) || (env.PAGINATION_MODE === Const.PAGINATION_MODE.CLASSIC && !env.isMobile)) {
        window.scrollTo(0, 0)
      }

      if (onLoad) {
        onLoad({ rows: _data.resultData, rowCount: _totalRecords })
      }
    } catch (err) {
      helper.error(err)
    } finally {
      setLoading(false)
      setInit(false)
    }
  }

  useEffect(() => {
    if (suppliers) {
      if (suppliers.length > 0) {
        fetchData(page, suppliers, pickupLocation, carSpecs, _carType, gearbox, mileage, fuelPolicy, deposit, ranges, multimedia, rating, seats)
      } else {
        setRows([])
        setFetch(false)
        if (onLoad) {
          onLoad({ rows: [], rowCount: 0 })
        }
        setInit(false)
      }
    }
  }, [page, suppliers, pickupLocation, pickupCoordinates, carSpecs, _carType, gearbox, mileage, fuelPolicy, deposit, ranges, multimedia, rating, seats, from, to]) // eslint-disable-line react-hooks/exhaustive-deps

  useEffect(() => {
    if (cars) {
      setRows(cars)
      setFetch(false)
      if (onLoad) {
        onLoad({ rows: cars, rowCount: cars.length })
      }
      setLoading(false)
    }
  }, [cars]) // eslint-disable-line react-hooks/exhaustive-deps

  useEffect(() => {
    setPage(1)
  }, [suppliers, pickupLocation, pickupCoordinates, carSpecs, _carType, gearbox, mileage, fuelPolicy, deposit, ranges, multimedia, rating, seats, from, to])

  useEffect(() => {
    if (reload) {
      setPage(1)
      fetchData(1, suppliers, pickupLocation, carSpecs, _carType, gearbox, mileage, fuelPolicy, deposit, ranges, multimedia, rating, seats)
    }
  }, [reload, suppliers, pickupLocation, pickupCoordinates, carSpecs, _carType, gearbox, mileage, fuelPolicy, deposit, ranges, multimedia, rating, seats]) // eslint-disable-line react-hooks/exhaustive-deps

  return (
    <>
      <section className={`${className ? `${className} ` : ''}car-list`}>
        {rows.length === 0
          ? !init
          && !loading
          && !carListLoading
          && (
            <div className="zero-result-recovery-card">
              <div className="recovery-header">
                <span className="recovery-badge">No direct matches for selected dates</span>
                <h3 className="recovery-title">No vehicles match this search</h3>
                <p className="recovery-subtitle">
                  Try different dates, adjust your filters, or search another pickup location.
                </p>
              </div>
              <div className="recovery-actions">
                {from && to && onDateChange && (
                  <div className="recovery-section">
                    <div className="recovery-section-title">Try another date</div>
                    <div className="recovery-chips">
                      {[1, 3, 7].map((offset) => {
                        const start = addDays(from, offset)
                        const end = addDays(to, offset)
                        return (
                          <button type="button" key={offset} className="recovery-chip date-chip" onClick={() => onDateChange(start, end)}>
                            {format(start, 'd MMM')} – {format(end, 'd MMM')}
                          </button>
                        )
                      })}
                    </div>
                  </div>
                )}
                {onHubChange && nearbyHubs.length > 0 && (
                  <div className="recovery-section">
                    <div className="recovery-section-title">Nearby pickup locations</div>
                    <div className="recovery-chips">
                      {nearbyHubs.map((hub) => (
                        <button key={hub._id} type="button" className="recovery-chip hub-chip" onClick={() => onHubChange(hub)}>
                          {hub.name}
                        </button>
                      ))}
                    </div>
                  </div>
                )}
              </div>
            </div>
          )
          : ((from && to && pickupLocation && dropOffLocation) || hidePrice) // || (hidePrice && booking))
          && (
            <>
              {totalRecords > 0 && (
                <div className="title">
                  <div className="bookcars">
                    <span>{strings.TITLE_1}</span>
                    <span className="title-bookcars">{env.WEBSITE_NAME}</span>
                    <span>{strings.TITLE_2}</span>
                  </div>
                  <div className="car-count">
                    {`(${totalRecords} ${totalRecords === 1 ? strings.TITLE_CAR_AVAILABLE : strings.TITLE_CARS_AVAILABLE})`}
                  </div>
                </div>
              )}

              {rows.map((car) => (
                <Car
                  key={car._id}
                  car={car}
                  booking={booking}
                  rentalMode={rentalMode}
                  pickupLocation={pickupLocation}
                  dropOffLocation={dropOffLocation}
                  from={from as Date}
                  to={to as Date}
                  pickupLocationName={pickupLocationName}
                  distance={distance}
                  hideSupplier={hideSupplier}
                  sizeAuto={sizeAuto}
                  hidePrice={hidePrice}
                />
              ))}
            </>
          )}
        {loading && <Progress />}
      </section>
      {env.PAGINATION_MODE === Const.PAGINATION_MODE.CLASSIC && !env.isMobile && (
        <Pager page={page} pageSize={env.CARS_PAGE_SIZE} rowCount={rowCount} totalRecords={totalRecords} onNext={() => setPage(page + 1)} onPrevious={() => setPage(page - 1)} />
      )}
    </>
  )
}

export default CarList

import React, { useState, useEffect } from 'react'
import { Controller, useForm, useWatch } from 'react-hook-form'
import { zodResolver } from '@hookform/resolvers/zod'
import { useNavigate } from 'react-router-dom'
import {
  FormControl,
  Button,
  FormControlLabel,
  Checkbox,
  FormHelperText,
  TextField,
  Stack,
} from '@mui/material'
import { MyLocation } from '@mui/icons-material'
import { addHours } from 'date-fns'
import * as bookcarsTypes from ':bookcars-types'
import * as bookcarsHelper from ':bookcars-helper'
import { strings as commonStrings } from '@/lang/common'
import { strings } from '@/lang/search-form'
import * as UserService from '@/services/UserService'
import * as LocationService from '@/services/LocationService'
import LocationSelectList from '@/components/LocationSelectList'
import DateTimePicker from '@/components/DateTimePicker'
import { schema, FormFields, LocationField } from '@/models/SearchForm'
import { useSetting } from '@/context/SettingContext'

import '@/assets/css/search-form.css'

const DEFAULT_SEARCH_SETTINGS = {
  minPickupHours: 3,
  minRentalHours: 24,
  minPickupDropoffHour: 6,
  maxPickupDropoffHour: 22,
}

interface SearchFormProps {
  pickupLocation?: string
  dropOffLocation?: string
  ranges?: bookcarsTypes.CarRange[]
  onCancel?: () => void
}

const SearchForm = ({
  pickupLocation: __pickupLocation,
  dropOffLocation: __dropOffLocation,
  ranges: __ranges,
  onCancel,
}: SearchFormProps) => {
  const navigate = useNavigate()

  const nearestPickupPoint = async (latitude: number, longitude: number) => {
    const points = await LocationService.getLocationsWithPosition()
    const distanceKm = (lat: number, lon: number) => {
      const radians = (value: number) => value * Math.PI / 180
      const dLat = radians(lat - latitude)
      const dLon = radians(lon - longitude)
      const a = Math.sin(dLat / 2) ** 2
        + Math.cos(radians(latitude)) * Math.cos(radians(lat)) * Math.sin(dLon / 2) ** 2
      return 6371 * 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a))
    }
    const nearest = points
      .filter((point) => Number.isFinite(point.latitude) && Number.isFinite(point.longitude))
      .map((point) => ({ point, distance: distanceKm(point.latitude!, point.longitude!) }))
      .sort((a, b) => a.distance - b.distance)[0]

    return nearest && nearest.distance <= 50 ? nearest.point : undefined
  }

  const { settings } = useSetting()
  const searchSettings = settings || DEFAULT_SEARCH_SETTINGS

  const [pickupLocationId, setPickupLocationId] = useState('')
  const [dropOffLocationId, setDropOffLocationId] = useState('')
  const [minTime, setMinTime] = useState<Date | null>(null)
  const [maxTime, setMaxTime] = useState<Date | null>(null)
  const [minDate, setMinDate] = useState<Date | null>(null)
  const [fromMinDate, setFromMinDate] = useState<Date | null>(null)
  const [ranges, setRanges] = useState(bookcarsHelper.getAllRanges())
  const [pickupPlace, setPickupPlace] = useState('')
  const [pickupCoordinates, setPickupCoordinates] = useState<{ latitude: number; longitude: number; name: string }>()
  const [placeError, setPlaceError] = useState('')
  const [rentalMode, setRentalMode] = useState<bookcarsTypes.RentalMode>(bookcarsTypes.RentalMode.SelfDrive)

  useEffect(() => {
    if (searchSettings) {
      const _minTime = new Date()
      _minTime.setHours(searchSettings.minPickupDropoffHour, 0, 0, 0)
      setMinTime(_minTime)

      const _maxTime = new Date()
      _maxTime.setHours(searchSettings.maxPickupDropoffHour, 0, 0, 0)
      setMaxTime(_maxTime)

      let _minDate = new Date()
      _minDate = addHours(_minDate, searchSettings.minPickupHours)

      setFromMinDate(_minDate)
      setMinDate(_minDate)
    }
  }, [searchSettings])

  const {
    register,
    handleSubmit,
    control,
    setValue,
    formState: { errors, isSubmitting },
    setError,
    clearErrors,
  } = useForm<FormFields>({
    resolver: zodResolver(schema),
    mode: 'onSubmit',
    defaultValues: {
      sameLocation: true,
    }
  })

  const from = useWatch({ control, name: 'from' })
  const to = useWatch({ control, name: 'to' })
  const pickupLocation = useWatch({ control, name: 'pickupLocation' })
  const dropOffLocation = useWatch({ control, name: 'dropOffLocation' })
  const sameLocation = useWatch({ control, name: 'sameLocation' })

  useEffect(() => {
    if (searchSettings) {
      const _from = new Date()
      if (searchSettings.minPickupHours < 72) {
        _from.setDate(_from.getDate() + 3)
      } else {
        _from.setDate(_from.getDate() + Math.ceil(searchSettings.minPickupHours / 24) + 1)
      }
      _from.setHours(10)
      _from.setMinutes(0)
      _from.setSeconds(0)
      _from.setMilliseconds(0)

      const _to = new Date(_from)
      if (searchSettings.minRentalHours < 72) {
        _to.setDate(_to.getDate() + 3)
      } else {
        _to.setDate(_to.getDate() + Math.ceil(searchSettings.minRentalHours / 24) + 1)
      }

      let __minDate = new Date()
      __minDate = addHours(__minDate, searchSettings.minRentalHours)

      setMinDate(__minDate)
      setValue('from', _from)
      setValue('to', _to)
    }
  }, [searchSettings]) // eslint-disable-line react-hooks/exhaustive-deps

  useEffect(() => {
    const init = async () => {
      if (__pickupLocation) {
        const location = await LocationService.getLocation(__pickupLocation) as LocationField
        setValue('pickupLocation', location)
        setPickupLocationId(__pickupLocation)
        if (sameLocation) {
          setValue('dropOffLocation', location)
          setDropOffLocationId(__pickupLocation)
        } else {
          setValue('sameLocation', dropOffLocationId === __pickupLocation)
        }
      }
    }
    init()
  }, [__pickupLocation]) // eslint-disable-line react-hooks/exhaustive-deps

  useEffect(() => {
    const init = async () => {
      if (__dropOffLocation) {
        const location = await LocationService.getLocation(__dropOffLocation) as LocationField
        setValue('dropOffLocation', location)
        setDropOffLocationId(__dropOffLocation)
        setValue('sameLocation', pickupLocationId === __dropOffLocation)
      }
    }
    init()
  }, [__dropOffLocation]) // eslint-disable-line react-hooks/exhaustive-deps

  useEffect(() => {
    setRanges(__ranges || bookcarsHelper.getAllRanges())
  }, [__ranges])

  const validateHour = (hour: number) => {
    return hour >= searchSettings.minPickupDropoffHour && hour <= searchSettings.maxPickupDropoffHour
  }

  const validateTimes = () => {
    let valid = true
    const minPickupDuration = searchSettings.minPickupHours * 60 * 60 * 1000
    const minRentalDuration = searchSettings.minRentalHours * 60 * 60 * 1000

    if (from) {
      let __minDate = new Date(from)
      __minDate = addHours(__minDate, searchSettings.minRentalHours)
      setMinDate(__minDate)

      const minPickupTime = from.getTime() - Date.now()

      if (minPickupTime < minPickupDuration) {
        setError('from', { message: strings.MIN_PICK_UP_HOURS_ERROR })
        valid = false
      } else {
        if (errors.from) {
          clearErrors('from')
        }
      }

      const hourValid = validateHour(from.getHours())
      if (!hourValid) {
        setError('from', { message: strings.INVALID_PICK_UP_TIME })
        valid = false
      }
    }

    if (from && to) {
      const rentalDuration = to.getTime() - from.getTime()

      if (from.getTime() > to.getTime()) {
        const _to = new Date(from)
        if (searchSettings.minRentalHours < 24) {
          _to.setDate(_to.getDate() + 1)
        } else {
          _to.setDate(_to.getDate() + Math.ceil(searchSettings.minRentalHours / 24) + 1)
        }
        const _from = new Date(from)
        const fromHourValid = validateHour(_from.getHours())
        if (!fromHourValid) {
          _from.setHours(searchSettings.minPickupDropoffHour)
          setValue('from', _from)
        }
        const toHourValid = validateHour(_to.getHours())
        if (!toHourValid) {
          _to.setHours(searchSettings.minPickupDropoffHour)
        }
        setValue('to', _to)
      } else if (rentalDuration < minRentalDuration) {
        setError('to', { message: strings.MIN_RENTAL_HOURS_ERROR })
        valid = false
      } else {
        if (errors.to) {
          clearErrors('to')
        }
      }

      const hourValid = validateHour(to.getHours())
      if (!hourValid) {
        setError('to', { message: strings.INVALID_DROP_OFF_TIME })
        valid = false
      }
    }

    return valid
  }

  useEffect(() => {
    validateTimes()
  }, [from, to]) // eslint-disable-line react-hooks/exhaustive-deps

  // Use fallback rules while remote settings are unavailable so search stays visible.
  if (!minDate || !fromMinDate || !minTime || !maxTime) {
    return null
  }

  const handlePickupLocationChange = async (values: bookcarsTypes.Option[]) => {
    setPickupPlace('')
    setPickupCoordinates(undefined)
    setPlaceError('')
    const _pickupLocationId = (values.length > 0 && values[0]._id) || ''
    setPickupLocationId(_pickupLocationId)

    if (_pickupLocationId) {
      const location = await LocationService.getLocation(_pickupLocationId) as LocationField
      setValue('pickupLocation', location)
      if (sameLocation) {
        setValue('dropOffLocation', location)
      }
    } else {
      setValue('pickupLocation', null)
    }

    if (sameLocation) {
      setDropOffLocationId(_pickupLocationId)
    }
  }

  const handleSameLocationChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { checked } = e.target
    setValue('sameLocation', checked)

    if (checked) {
      setDropOffLocationId(pickupLocationId)
    } else {
      setDropOffLocationId('')
    }
  }

  const handleDropOffLocationChange = async (values: bookcarsTypes.Option[]) => {
    const _dropOffLocationId = (values.length > 0 && values[0]._id) || ''
    setDropOffLocationId(_dropOffLocationId)

    if (_dropOffLocationId) {
      const location = await LocationService.getLocation(_dropOffLocationId) as LocationField
      setValue('dropOffLocation', location)
    } else {
      setValue('dropOffLocation', null)
    }
  }

  const onSubmit = async (data: FormFields) => {
    const valid = validateTimes()
    if (!valid) {
      return
    }

    if (!data.from || !data.to) {
      return
    }

    let resolvedCoordinates = pickupCoordinates
    if (!resolvedCoordinates && pickupPlace.trim()) {
      try {
        const place = await LocationService.resolvePlace(pickupPlace.trim())
        resolvedCoordinates = { ...place, name: place.name || pickupPlace.trim() }
      } catch (err) {
        setPlaceError('We could not find that place. Try a Pakistani city or use your current location.')
        return
      }
    }

    if (resolvedCoordinates) {
      let nearestPoint
      try {
        nearestPoint = await nearestPickupPoint(resolvedCoordinates.latitude, resolvedCoordinates.longitude)
      } catch (err) {
        setPlaceError('Pickup locations could not be loaded. Please try again.')
        return
      }
      if (!nearestPoint) {
        setPlaceError('There are no SafarRent pickup points within 50 km yet. Choose a listed pickup city instead.')
        return
      }

      if (!sameLocation && (!data.dropOffLocation || !dropOffLocationId)) {
        return
      }
      navigate('/search', {
        state: {
          pickupLocationId: nearestPoint._id,
          dropOffLocationId: sameLocation ? nearestPoint._id : dropOffLocationId,
          pickupCoordinates: {
            latitude: resolvedCoordinates.latitude,
            longitude: resolvedCoordinates.longitude,
          },
          pickupPlace: resolvedCoordinates.name,
          from: data.from,
          to: data.to,
          ranges,
          rentalMode,
        },
      })
      return
    }

    if (!data.pickupLocation || !data.dropOffLocation) {
      return
    }

    setTimeout(navigate, 0, '/search', {
      state: {
        pickupLocationId: pickupLocationId,
        dropOffLocationId: dropOffLocationId,
        from: data.from,
        to: data.to,
        ranges,
        rentalMode,
      },
    })
  }

  return (
    <form onSubmit={handleSubmit(onSubmit)} className="home-search-form">
      {/* Top Controls Row */}
      <div className="home-search-top-row">
        <div className="rental-mode-pill-group" role="group" aria-label="Rental mode selection">
          <button
            type="button"
            className={`rental-mode-pill ${rentalMode === bookcarsTypes.RentalMode.SelfDrive ? 'active' : ''}`}
            aria-pressed={rentalMode === bookcarsTypes.RentalMode.SelfDrive}
            onClick={() => setRentalMode(bookcarsTypes.RentalMode.SelfDrive)}
          >
            Self-drive
          </button>
          <button
            type="button"
            className={`rental-mode-pill ${rentalMode === bookcarsTypes.RentalMode.WithDriver ? 'active' : ''}`}
            aria-pressed={rentalMode === bookcarsTypes.RentalMode.WithDriver}
            onClick={() => setRentalMode(bookcarsTypes.RentalMode.WithDriver)}
          >
            With chauffeur
          </button>
        </div>

        <FormControl className="chk-same-location">
          <FormControlLabel control={<Checkbox checked={sameLocation} onChange={handleSameLocationChange} />} label={strings.DROP_OFF} />
        </FormControl>
      </div>

      {/* Locations Row */}
      <div className="home-search-locations-row">
        <FormControl fullWidth className="pickup-location">
          <LocationSelectList
            {...register('pickupLocation')}
            label={commonStrings.PICK_UP_LOCATION}
            hidePopupIcon
            init
            required={!pickupPlace && !pickupCoordinates}
            variant="outlined"
            value={pickupLocation as bookcarsTypes.Location}
            onChange={handlePickupLocationChange}
          />
        </FormControl>

        <FormControl fullWidth className="pickup-place">
          <Stack direction="row" spacing={1} alignItems="flex-start">
            <TextField
              fullWidth
              label="Search any place in Pakistan"
              placeholder="Enter a city or area"
              value={pickupPlace}
              onChange={(event) => {
                setPickupPlace(event.target.value)
                setPickupCoordinates(undefined)
                setPlaceError('')
                if (event.target.value) {
                  setPickupLocationId('geo')
                  setValue('pickupLocation', null)
                  if (sameLocation) {
                    setDropOffLocationId('geo')
                    setValue('dropOffLocation', null)
                  }
                }
              }}
              variant="outlined"
            />
            <Button
              type="button"
              variant="outlined"
              startIcon={<MyLocation />}
              sx={{ whiteSpace: 'nowrap', minWidth: '160px', height: '56px' }}
              onClick={() => {
                if (!navigator.geolocation) {
                  setPlaceError('Location access is not available in this browser.')
                  return
                }
                navigator.geolocation.getCurrentPosition(
                  ({ coords }) => {
                    setPickupCoordinates({ latitude: coords.latitude, longitude: coords.longitude, name: 'Your current location' })
                    setPickupPlace('Current location')
                    setPickupLocationId('')
                    setValue('pickupLocation', null)
                    if (sameLocation) {
                      setDropOffLocationId('')
                      setValue('dropOffLocation', null)
                    }
                    setPlaceError('')
                  },
                  () => setPlaceError('Allow location access or enter a city to search nearby cars.'),
                  { enableHighAccuracy: false, timeout: 8000, maximumAge: 60000 },
                )
              }}
            >
              Use my location
            </Button>
          </Stack>
          <FormHelperText error={!!placeError}>{placeError || (pickupCoordinates ? `${pickupCoordinates.name} selected. Searching approved vehicles within 50 km.` : 'Searches approved vehicles near registered pickup points (within 50 km).')}</FormHelperText>
        </FormControl>

        {!sameLocation && (
          <FormControl fullWidth className="drop-off-location">
            <LocationSelectList
              {...register('dropOffLocation')}
              label={commonStrings.DROP_OFF_LOCATION}
              hidePopupIcon
              init
              value={dropOffLocation as bookcarsTypes.Location}
              required
              variant="outlined"
              onChange={handleDropOffLocationChange}
            />
          </FormControl>
        )}
      </div>

      {/* Dates & Search CTA Row */}
      <div className="home-search-dates-row">
        <FormControl fullWidth className="from">
          <Controller
            name="from"
            control={control}
            render={({ field }) => (
              <DateTimePicker
                {...field}
                variant="outlined"
                label={strings.PICK_UP_DATE}
                value={field.value || undefined}
                minDate={fromMinDate}
                minTime={minTime}
                maxTime={maxTime}
                onChange={(date) => {
                  field.onChange(date)
                }}
                language={UserService.getLanguage()}
              />
            )}
          />
          <FormHelperText error={!!errors.from}>{errors.from?.message}</FormHelperText>
        </FormControl>

        <FormControl fullWidth className="to">
          <Controller
            name="to"
            control={control}
            render={({ field }) => (
              <DateTimePicker
                {...field}
                variant="outlined"
                label={strings.DROP_OFF_DATE}
                value={field.value || undefined}
                minDate={minDate}
                minTime={minTime}
                maxTime={maxTime}
                onChange={(date) => {
                  field.onChange(date)
                }}
                language={UserService.getLanguage()}
              />
            )}
          />
          <FormHelperText error={!!errors.to}>{errors.to?.message}</FormHelperText>
        </FormControl>

        <Button type="submit" variant="contained" className="btn-search" disabled={isSubmitting}>
          {commonStrings.SEARCH}
        </Button>
        {onCancel && (
          <Button
            variant="outlined"
            color="inherit"
            className="btn-cancel"
            onClick={() => {
              onCancel()
            }}
          >
            {commonStrings.CANCEL}
          </Button>
        )}
      </div>
    </form>
  )
}

export default SearchForm

