//
// Make sure to call `loadStripe` outside of a component’s render to avoid
// recreating the `Stripe` object on every render.
//
const onlinePaymentConfigured = env.PAYMENT_GATEWAY === bookcarsTypes.PaymentGateway.Stripe
  ? /^pk_(live|test)_/.test(env.STRIPE_PUBLISHABLE_KEY)
  : Boolean(env.PAYPAL_CLIENT_ID) && !env.PAYPAL_CLIENT_ID.includes('PAYPAL_CLIENT_ID')
const stripePromise = env.PAYMENT_GATEWAY === bookcarsTypes.PaymentGateway.Stripe && onlinePaymentConfigured ? loadStripe(env.STRIPE_PUBLISHABLE_KEY) : null

const Checkout = () => {
  const location = useLocation()
  const navigate = useNavigate()
  const { reCaptchaLoaded, generateReCaptchaToken } = useRecaptchaContext() as RecaptchaContextType

  const [user, setUser] = useState<bookcarsTypes.User>()
  const [car, setCar] = useState<bookcarsTypes.Car>()
  const [pickupLocation, setPickupLocation] = useState<bookcarsTypes.Location>()
  const [dropOffLocation, setDropOffLocation] = useState<bookcarsTypes.Location>()
  const [from, setFrom] = useState<Date>()
  const [to, setTo] = useState<Date>()
  const [visible, setVisible] = useState(false)
  const [authenticated, setAuthenticated] = useState(false)
  const [language, setLanguage] = useState(env.DEFAULT_LANGUAGE)
  const [noMatch, setNoMatch] = useState(false)
  const [emailInfo, setEmailInfo] = useState(true)
  const [phoneInfo, setPhoneInfo] = useState(true)
  const [price, setPrice] = useState(0)
  const [depositPrice, setDepositPrice] = useState(0)
  const [basePaymentAmount, setBasePaymentAmount] = useState(0)
  const [success, setSuccess] = useState(false)
  const [loadingPage, setLoadingPage] = useState(true)
  const [recaptchaError, setRecaptchaError] = useState(false)
  const adRequired = true
  const [adManuallyChecked, setAdManuallyChecked] = useState(false)
  const [paymentFailed, setPaymentFailed] = useState(false)
  const [clientSecret, setClientSecret] = useState<string | null>(null)
  const [bookingId, setBookingId] = useState<string>()
  const [sessionId, setSessionId] = useState<string>()
  // const [distance, setDistance] = useState('')
  const [licenseRequired, setLicenseRequired] = useState(false)
  const [license, setLicense] = useState<string | null>(null)
  const [openMapDialog, setOpenMapDialog] = useState(false)
  const [payPalLoaded, setPayPalLoaded] = useState(false)
  const [payPalInit, setPayPalInit] = useState(false)
  const [payPalProcessing, setPayPalProcessing] = useState(false)
  const [rentalMode, setRentalMode] = useState<bookcarsTypes.RentalMode>(bookcarsTypes.RentalMode.WithDriver)
  const [tripScope, setTripScope] = useState<bookcarsTypes.TripScope>(bookcarsTypes.TripScope.IntraCity)
  const [quote, setQuote] = useState<BookingService.PakistanQuote>()

  const birthDateRef = useRef<HTMLInputElement | null>(null)
  const additionalDriverBirthDateRef = useRef<HTMLInputElement | null>(null)
  const additionalDriverEmailRef = useRef<HTMLInputElement | null>(null)
  const additionalDriverPhoneRef = useRef<HTMLInputElement | null>(null)

  const _locale = getDateLocale(language)

  const dateFormats: Record<string, string> = {
    fr: 'eee d LLL yyyy kk:mm',
    es: 'eee, d LLLL yyyy HH:mm',
    de: 'eee, d LLL yyyy HH:mm',
    pt: 'eee, d LLL yyyy HH:mm',
    it: 'eee, d LLL yyyy HH:mm',
    zh: 'yyyy年M月d日 eee HH:mm',
    ja: 'yyyy年M月d日 eee HH:mm',
  }
  const _format = dateFormats[language] || 'eee, d LLL yyyy, p'
  const bookingDetailHeight = env.SUPPLIER_IMAGE_HEIGHT + 10
  const days = bookcarsHelper.days(from, to)
  const daysLabel = from && to && `${helper.getDaysShort(language, days)} (${bookcarsHelper.capitalize(format(from, _format, { locale: _locale }))} - ${bookcarsHelper.capitalize(format(to, _format, { locale: _locale }))})`

  const schema = createSchema(car)

  const {
    control,
    register,
    handleSubmit,
    setValue,
    formState: { errors, isSubmitting },
    clearErrors,
    setFocus,
    trigger,
  } = useForm<FormFields>({
    resolver: zodResolver(schema),
    mode: 'onBlur',
    shouldUnregister: false,
    defaultValues: {
      additionalDriverEmail: '',
      additionalDriverPhone: '',
    }
  })

  const additionalDriverEmail = useWatch({ control, name: 'additionalDriverEmail' })
  const additionalDriverPhone = useWatch({ control, name: 'additionalDriverPhone' })

  const additionalDriver = useWatch({ control, name: 'additionalDriver' })
  const payLater = useWatch({ control, name: 'payLater' })
  const payDeposit = useWatch({ control, name: 'payDeposit' })
  const payInFull = useWatch({ control, name: 'payInFull' })
  const cancellation = useWatch({ control, name: 'cancellation' }) || false
  const amendments = useWatch({ control, name: 'amendments' }) || false
  const theftProtection = useWatch({ control, name: 'theftProtection' }) || false
  const collisionDamageWaiver = useWatch({ control, name: 'collisionDamageWaiver' }) || false
  const fullInsurance = useWatch({ control, name: 'fullInsurance' }) || false

  const updateQuote = async (
    mode = rentalMode,
    scope = tripScope,
  ) => {
    if (!car || !from || !to) {
return
}
    try {
      const result = await BookingService.calculatePakistanQuote({
        carId: car._id,
        from,
        to,
        rentalMode: mode,
        tripScope: scope,
        options: { cancellation, amendments, theftProtection, collisionDamageWaiver, fullInsurance, additionalDriver },
      })
      setQuote(result)
      setPrice(result.baseRentPKR + result.driverAllowancePKR + result.outOfCitySurchargePKR)
      setDepositPrice(result.securityDepositPKR)
    } catch {
      setQuote(undefined)
    }
  }

  const validatePhone = (phone: string) => {
    return isPakistanPhone(phone)
  }

  const onSubmit = async (data: FormFields) => {
    try {
      if (!data.payLater && !onlinePaymentConfigured) {
        helper.error()
        return
      }
      if (!car || !pickupLocation || !dropOffLocation || !from || !to) {
        helper.error()
        return
      }

      const submittedCnic = data.cnicNumber || user?.cnicNumber || ''
      const submittedLicenseNumber = data.drivingLicenseNumber || user?.drivingLicenseNumber || ''
      if (!/^\d{5}-\d{7}-\d$/.test(submittedCnic)) {
        helper.error(undefined, 'Enter a valid CNIC in your profile or the driver details to continue.')
        return
      }
      if (rentalMode === bookcarsTypes.RentalMode.SelfDrive
        && (user?.kycStatus !== bookcarsTypes.KycStatus.Verified || !submittedLicenseNumber)) {
        helper.error(undefined, 'Self-drive requires an admin-verified CNIC and driving license number. Complete KYC in Settings first.')
        return
      }

      let recaptchaToken = ''
      if (reCaptchaLoaded) {
        recaptchaToken = await generateReCaptchaToken()
        if (!(await helper.verifyReCaptcha(recaptchaToken))) {
          recaptchaToken = ''
        }
      }

      if (env.RECAPTCHA_ENABLED && !recaptchaToken) {
        setRecaptchaError(true)
        return
      }

      if (car.supplier.licenseRequired && !license) {
        setLicenseRequired(true)
        return
      }

      setPaymentFailed(false)

      let driver: bookcarsTypes.User | undefined
      let _additionalDriver: bookcarsTypes.AdditionalDriver | undefined

      if (!authenticated) {
        driver = {
          email: data.email,
          phone: data.phone,
          fullName: data.fullName!,
          birthDate: data.birthDate,
          language: UserService.getLanguage(),
          license: license || undefined,
          cnicNumber: submittedCnic,
          drivingLicenseNumber: submittedLicenseNumber,
        }
      }

      //
      // Payments are always made in the base currency.
      // The prices displayed in the selected currency are only estimates.
      //
      const currentQuote = await BookingService.calculatePakistanQuote({
        carId: car._id,
        from,
        to,
        rentalMode,
        tripScope,
        options: {
          cancellation: data.cancellation,
          amendments: data.amendments,
          theftProtection: data.theftProtection,
          collisionDamageWaiver: data.collisionDamageWaiver,
          fullInsurance: data.fullInsurance,
          additionalDriver,
        },
      })
      setQuote(currentQuote)
      const baseTotalPrice = currentQuote.baseRentPKR + currentQuote.driverAllowancePKR + currentQuote.outOfCitySurchargePKR
      let baseDepositPrice = currentQuote.securityDepositPKR

      let basePrice = baseTotalPrice
      if (payDeposit) {
        basePrice = baseDepositPrice
      } else if (payInFull) {
        basePrice = baseTotalPrice + baseDepositPrice
      }
      basePrice = Number(basePrice.toFixed(2))
      setBasePaymentAmount(basePrice)
      const booking: bookcarsTypes.Booking = {
        supplier: car.supplier._id as string,
        car: car._id,
        driver: authenticated ? user?._id : undefined,
        pickupLocation: pickupLocation._id,
        dropOffLocation: dropOffLocation._id,
        from,
        to,
        status: bookcarsTypes.BookingStatus.Pending,
        rentalMode,
        tripScope,
        priceBreakdown: {
          baseRentPkr: currentQuote.baseRentPKR,
          driverAllowancePkr: currentQuote.driverAllowancePKR,
          outOfCitySurchargePkr: currentQuote.outOfCitySurchargePKR,
          securityDepositPkr: currentQuote.securityDepositPKR,
          totalPayablePkr: currentQuote.totalPayablePKR,
        },
        cancellation: data.cancellation,
        amendments: data.amendments,
        theftProtection: data.theftProtection,
        collisionDamageWaiver: data.collisionDamageWaiver,
        fullInsurance: data.fullInsurance,
        additionalDriver,
        price: basePrice,
      }

      if (adRequired && additionalDriver && data.additionalDriverBirthDate) {
        _additionalDriver = {
          fullName: data.additionalDriverFullName!,
          email: data.additionalDriverEmail!,
          phone: data.additionalDriverPhone!,
          birthDate: data.additionalDriverBirthDate,
        }
      }

      //
      // Stripe Payment Gateway
      //
      let _customerId: string | undefined
      let _sessionId: string | undefined
      if (!payLater) {
        if (env.PAYMENT_GATEWAY === bookcarsTypes.PaymentGateway.Stripe) {
          const name = bookcarsHelper.truncateString(`${env.WEBSITE_NAME} - ${car.name}`, StripeService.ORDER_NAME_MAX_LENGTH)
          const _description = `${env.WEBSITE_NAME} - ${car.name} - ${daysLabel} - ${pickupLocation._id === dropOffLocation._id ? pickupLocation.name : `${pickupLocation.name} - ${dropOffLocation.name}`}`
          const description = bookcarsHelper.truncateString(_description, StripeService.ORDER_DESCRIPTION_MAX_LENGTH)

          const payload: bookcarsTypes.CreatePaymentPayload = {
            amount: basePrice,
            currency: env.BASE_CURRENCY,
            locale: language,
            receiptEmail: (!authenticated ? driver?.email : user?.email) as string,
            name,
            description,
            customerName: (!authenticated ? driver?.fullName : user?.fullName) as string,
          }
          const res = await StripeService.createCheckoutSession(payload)
          setClientSecret(res.clientSecret)
          _sessionId = res.sessionId
          _customerId = res.customerId
        } else {
          // Generate a unique session ID for PayPal checkout
          _sessionId = nanoid()
        }
      } else {
        // Generate a unique session ID for pay later checkout
        _sessionId = nanoid()
      }

      booking.isDeposit = payDeposit
      booking.isPayedInFull = payInFull

      const payload: bookcarsTypes.CheckoutPayload = {
        driver,
        booking,
        additionalDriver: _additionalDriver,
        payLater: !!data.payLater,
        sessionId: _sessionId,
        customerId: _customerId,
        payPal: env.PAYMENT_GATEWAY === bookcarsTypes.PaymentGateway.PayPal,
        cnicNumber: authenticated ? submittedCnic : undefined,
        drivingLicenseNumber: authenticated ? submittedLicenseNumber : undefined,
      }

      const { status, bookingId: _bookingId } = await BookingService.checkout(payload)

      if (status === 200) {
        setBookingId(_bookingId)
        setSessionId(_sessionId)
        if (payLater) {
          setVisible(false)
          setSuccess(true)
        } else if (env.PAYMENT_GATEWAY === bookcarsTypes.PaymentGateway.PayPal) {
          // Set payPalLoaded ONLY AFTER bookingId is set
          setPayPalLoaded(true)
        }
      } else {
        helper.error()
      }
    } catch (err) {
      if ((err as any)?.status === 400) {
        helper.error(err, strings.INVALID_REQUEST)
      } else {
        helper.error(err)
      }
    }
  }

  const onError = () => {
    const firstErrorField = Object.keys(errors)[0] as keyof FormFields
    if (firstErrorField) {
      if (firstErrorField === 'birthDate' && birthDateRef.current) {
        birthDateRef.current.focus()
      }
      if (firstErrorField === 'additionalDriverBirthDate' && additionalDriverBirthDateRef.current) {
        additionalDriverBirthDateRef.current.focus()
      } else if (firstErrorField === 'additionalDriverEmail' && additionalDriverEmailRef.current) {
        additionalDriverEmailRef.current.focus()
      } else if (firstErrorField === 'additionalDriverPhone' && additionalDriverPhoneRef.current) {
        additionalDriverPhoneRef.current.focus()
      } else {
        setFocus(firstErrorField)
      }
    }
  }

  const onLoad = async (_user?: bookcarsTypes.User) => {
    setUser(_user)
    setAuthenticated(_user !== undefined)
    setLanguage(UserService.getLanguage())

    const { state } = location
    if (!state) {
      setNoMatch(true)
      setLoadingPage(false)
      return
    }

    const { carId } = state
    const { pickupLocationId } = state
    const { dropOffLocationId } = state
    const { from: _from } = state
    const { to: _to } = state

    if (!carId || !pickupLocationId || !dropOffLocationId || !_from || !_to) {
      setNoMatch(true)
      setLoadingPage(false)
      return
    }

    let _car
    let _pickupLocation
    let _dropOffLocation

    try {
      _car = await CarService.getCar(carId)
      if (!_car) {
        setNoMatch(true)
        setLoadingPage(false)
        return
      }

      _pickupLocation = await LocationService.getLocation(pickupLocationId)

      if (!_pickupLocation) {
        setNoMatch(true)
        return
      }

      // if (_pickupLocation.latitude && _pickupLocation.longitude) {
      //   const l = await helper.getLocation()
      //   if (l) {
      //     const d = bookcarsHelper.distance(_pickupLocation.latitude, _pickupLocation.longitude, l[0], l[1], 'K')
      //     setDistance(bookcarsHelper.formatDistance(d, UserService.getLanguage()))
      //   }
      // }

      if (dropOffLocationId !== pickupLocationId) {
        _dropOffLocation = await LocationService.getLocation(dropOffLocationId)
      } else {
        _dropOffLocation = _pickupLocation
      }

      if (!_dropOffLocation) {
        setNoMatch(true)
        return
      }

      const priceChangeRate = _car.supplier.priceChangeRate || 0
      const _price = await PaymentService.convertPrice(bookcarsHelper.calculateTotalPrice(_car, _from, _to, priceChangeRate))
      let _depositPrice = _car.deposit > 0 ? await PaymentService.convertPrice(_car.deposit) : 0
      _depositPrice += _depositPrice * (priceChangeRate / 100)
      const initialMode = state.rentalMode === bookcarsTypes.RentalMode.SelfDrive && _car.selfDriveAvailable
        ? bookcarsTypes.RentalMode.SelfDrive
        : bookcarsTypes.RentalMode.WithDriver
      const initialScope = dropOffLocationId === pickupLocationId ? bookcarsTypes.TripScope.IntraCity : bookcarsTypes.TripScope.OutOfCity
      const initialQuote = await BookingService.calculatePakistanQuote({
        carId: _car._id,
        from: _from,
        to: _to,
        rentalMode: initialMode,
        tripScope: initialScope,
        options: {
          cancellation: _car.cancellation === 0,
          amendments: _car.amendments === 0,
          theftProtection: _car.theftProtection === 0,
          collisionDamageWaiver: _car.collisionDamageWaiver === 0,
          fullInsurance: _car.fullInsurance === 0,
        },
      })

      const included = (val: number) => val === 0

      setCar(_car)
      setQuote(initialQuote)
      setPrice(initialQuote.baseRentPKR + initialQuote.driverAllowancePKR + initialQuote.outOfCitySurchargePKR || _price)
      setDepositPrice(initialQuote.securityDepositPKR || _depositPrice)
      setPickupLocation(_pickupLocation)
      setDropOffLocation(_dropOffLocation)
      setFrom(_from)
      setTo(_to)
      setValue('cancellation', included(_car.cancellation))
      setValue('amendments', included(_car.amendments))
      setValue('theftProtection', included(_car.theftProtection))
      setValue('collisionDamageWaiver', included(_car.collisionDamageWaiver))
      setValue('fullInsurance', included(_car.fullInsurance))
      setValue('cnicNumber', _user?.cnicNumber || '')
      setValue('drivingLicenseNumber', _user?.drivingLicenseNumber || '')
      setRentalMode(initialMode)
      setTripScope(dropOffLocationId === pickupLocationId ? bookcarsTypes.TripScope.IntraCity : bookcarsTypes.TripScope.OutOfCity)
      setLicense(_user?.license || null)
      setVisible(true)
    } catch (err) {
      helper.error(err)
      setNoMatch(true)
    } finally {
      setLoadingPage(false)
    }
  }

  const fareTotal = quote?.totalPayablePKR ?? (price + depositPrice)
  const demoAdvance = Math.round(fareTotal * 0.2)

  return (
    <>
      <Layout onLoad={onLoad} strict={false}>
        {!user?.blacklisted && visible && car && from && to && pickupLocation && dropOffLocation && (
          <>
            <div className="checkout">
              <div className="checkout-main-column">
                <Paper className="checkout-form" elevation={6}>
                  <div className="checkout-stepper-header">
                    <a className="stepper-step" href="#checkout-step-1">
                      <span className="step-number">1</span>
                      <span className="step-text">Rental options</span>
                    </a>
                    <span className="stepper-arrow">›</span>
                    <a className="stepper-step" href="#checkout-step-2">
                      <span className="step-number">2</span>
                      <span className="step-text">Identity details</span>
                    </a>
                    <span className="stepper-arrow">›</span>
                    <a className="stepper-step" href="#checkout-step-3">
                      <span className="step-number">3</span>
                      <span className="step-text">Payment</span>
                    </a>
                  </div>

                  <form onSubmit={handleSubmit(onSubmit, onError)}>
                    <div>
                      {/* STEP 1: Protection & Chauffeur */}
                      <div className="checkout-step-section" id="checkout-step-1">
                        <div className="checkout-step-title">
                          <span className="step-badge">STEP 1</span>
                          <h2>Protection & Chauffeur Experience</h2>
                        </div>

                        <section className="checkout-details-container" aria-label="Rental mode and Pakistani KYC">
                          <div className="checkout-info"><DriverIcon /><span>Select Rental Mode & Route Type</span></div>
                          <FormControl fullWidth>
                            <RadioGroup value={rentalMode} onChange={(event) => {
                              const next = event.target.value as bookcarsTypes.RentalMode
                              setRentalMode(next)
                              void updateQuote(next, tripScope)
                            }}>
                              <FormControlLabel value={bookcarsTypes.RentalMode.WithDriver} control={<Radio />} label="👔 With Executive Chauffeur (Relaxed travel, host-managed driver)" />
                              <FormControlLabel value={bookcarsTypes.RentalMode.SelfDrive} control={<Radio />} disabled={!car.selfDriveAvailable} label="🚗 Self-Drive (Requires verified CNIC & Pakistani Driving License)" />
                            </RadioGroup>
                            <div className="trip-scope-header">Route Terrain & Scope:</div>
                            <RadioGroup row value={tripScope} onChange={(event) => {
                              const next = event.target.value as bookcarsTypes.TripScope
                              setTripScope(next)
                              void updateQuote(rentalMode, next)
                            }}>
                              <FormControlLabel value={bookcarsTypes.TripScope.IntraCity} control={<Radio />} label="In-City Travel" />
                              <FormControlLabel value={bookcarsTypes.TripScope.OutOfCity} control={<Radio />} label="Inter-City Highway" />
                              <FormControlLabel value={bookcarsTypes.TripScope.NorthernTour} control={<Radio />} label="Northern Tour (4x4 Hill Routes)" disabled={car.terrainCapability !== bookcarsTypes.TerrainCapability.NorthernMountains} />
                            </RadioGroup>
                          </FormControl>
                        </section>

                        <CheckoutOptions
                          car={car}
                          from={from}
                          to={to}
                          language={language}
                          clientSecret={clientSecret}
                          payPalLoaded={payPalLoaded}
                          onPriceChange={() => {
 void updateQuote() 
}}
                          onAdManuallyCheckedChange={(value) => setAdManuallyChecked(value)}
                          onCancellationChange={(value) => setValue('cancellation', value)}
                          onAmendmentsChange={(value) => setValue('amendments', value)}
                          onTheftProtectionChange={(value) => setValue('theftProtection', value)}
                          onCollisionDamageWaiverChange={(value) => setValue('collisionDamageWaiver', value)}
                          onFullInsuranceChange={(value) => setValue('fullInsurance', value)}
                          onAdditionalDriverChange={(value) => setValue('additionalDriver', value)}
                        />
                      </div>

                      {/* STEP 2: 2-Minute CNIC & KYC */}
                      <div className="checkout-step-section" id="checkout-step-2">
                        <div className="checkout-step-title">
                          <span className="step-badge">STEP 2</span>
                          <h2>2-Minute CNIC & Digital KYC Verification</h2>
                        </div>

                        <section className="checkout-details-container">
                          <div className="checkout-info"><DriverIcon /><span>Pakistani National Identity (CNIC)</span></div>
                          <FormControl fullWidth margin="dense">
                            <InputLabel required>CNIC (12345-1234567-1)</InputLabel>
                            <OutlinedInput {...register('cnicNumber')} label="CNIC (12345-1234567-1)" autoComplete="off" placeholder="35201-1234567-1" />
                            <FormHelperText>Required by SBP & Government for vehicle release. Matches your Nadra registration.</FormHelperText>
                          </FormControl>
                          {rentalMode === bookcarsTypes.RentalMode.SelfDrive && (
                            <FormControl fullWidth margin="dense">
                              <InputLabel required>Driving License Number</InputLabel>
                              <OutlinedInput {...register('drivingLicenseNumber')} label="Driving License Number" autoComplete="off" placeholder="ICT-LE-12345" />
                              <FormHelperText>Required for self-drive. Must be valid on the trip dates.</FormHelperText>
                            </FormControl>
                          )}
                          {quote && <Alert severity="info" sx={{ mt: 1 }}>Your itemized PKR quote is ready.</Alert>}
                        </section>

                    <div className="checkout-details-container">
                      <div className="checkout-info">
                        <CarIcon />
                        <span>{strings.BOOKING_DETAILS}</span>
                      </div>
                      <div className="checkout-details">
                        <div className="checkout-detail" style={{ height: bookingDetailHeight }}>
                          <span className="checkout-detail-title">{strings.DAYS}</span>
                          <div className="checkout-detail-value">
                            {daysLabel}
                          </div>
                        </div>
                        <div className="checkout-detail" style={{ height: bookingDetailHeight }}>
                          <span className="checkout-detail-title">{commonStrings.PICK_UP_LOCATION}</span>
                          <div className="checkout-detail-value">{pickupLocation.name}</div>
                        </div>
                        <div className="checkout-detail" style={{ height: bookingDetailHeight }}>
                          <span className="checkout-detail-title">{commonStrings.DROP_OFF_LOCATION}</span>
                          <div className="checkout-detail-value">{dropOffLocation.name}</div>
                        </div>
                        <div className="checkout-detail" style={{ height: bookingDetailHeight }}>
                          <span className="checkout-detail-title">{strings.CAR}</span>
                          <div className="checkout-detail-value">{`${car.name} (${bookcarsHelper.formatPrice(price / days, commonStrings.CURRENCY, language)}${commonStrings.DAILY})`}</div>
                        </div>
                        {!env.HIDE_SUPPLIERS && (
                          <div className="checkout-detail" style={{ height: bookingDetailHeight }}>
                            <span className="checkout-detail-title">{commonStrings.SUPPLIER}</span>
                            <div className="checkout-detail-value">
                              <div className="car-supplier">
                                {car.supplier?.avatar && env.CDN_USERS
                                  ? <img src={bookcarsHelper.joinURL(env.CDN_USERS, car.supplier.avatar)} alt={car.supplier.fullName || 'Rental supplier'} style={{ height: env.SUPPLIER_IMAGE_HEIGHT }} />
                                  : <span className="car-supplier-avatar-fallback" aria-hidden="true">{car.supplier?.fullName?.slice(0, 1) || 'S'}</span>}
                                <span className="car-supplier-name">{car.supplier?.fullName || 'Rental supplier'}</span>
                              </div>
                            </div>
                          </div>
                        )}
                        <div className="checkout-detail" style={{ height: bookingDetailHeight }}>
                          <span className="checkout-detail-title">{strings.COST}</span>
                          <div className="checkout-detail-value booking-price">{bookcarsHelper.formatPrice(price, commonStrings.CURRENCY, language)}</div>
                        </div>
                      </div>
                    </div>

                    {!authenticated && (
                      <div className="driver-details">
                        <div className="checkout-info">
                          <DriverIcon />
                          <span>{strings.DRIVER_DETAILS}</span>
                        </div>
                        <div className="driver-details-form">
                          <FormControl fullWidth margin="dense">
                            <InputLabel className="required">{commonStrings.FULL_NAME}</InputLabel>
                            <OutlinedInput
                              {...register('fullName')}
                              type="text"
                              label={commonStrings.FULL_NAME}
                              required
                              error={!!errors.fullName}
                              autoComplete="off"
                            />
                          </FormControl>
                          <FormControl fullWidth margin="dense">
                            <InputLabel className="required">{commonStrings.EMAIL}</InputLabel>
                            <OutlinedInput
                              // {...register('email')}
                              type="text"
                              label={commonStrings.EMAIL}
                              error={!!errors.email}
                              required
                              autoComplete="off"
                              onChange={(e) => {
                                if (errors.email) {
                                  clearErrors('email')
                                }
                                setEmailInfo(false)
                                setValue('email', e.target.value)
                              }}
                              onBlur={(e) => {
                                trigger('email')
                                setEmailInfo(validator.isEmail(e.target.value))
                              }}
                            />
                            <FormHelperText error={!!errors.email}>
                              {(errors.email && errors.email.message) || ''}
                              {(emailInfo && !errors.email && strings.EMAIL_INFO) || ''}
                            </FormHelperText>
                          </FormControl>
                          <FormControl fullWidth margin="dense">
                            <InputLabel className="required">{commonStrings.PHONE}</InputLabel>
                            <OutlinedInput
                              // {...register('phone')}
                              type="text"
                              label={commonStrings.PHONE}
                              error={!!errors.phone}
                              required
                              autoComplete="off"
                              onChange={(e) => {
                                if (errors.phone) {
                                  clearErrors('phone')
                                }
                                setPhoneInfo(false)
                                setValue('phone', e.target.value)
                              }}
                              onBlur={(e) => {
                                trigger('phone')
                                setPhoneInfo(validatePhone(e.target.value))
                              }}
                            />
                            <FormHelperText error={!!errors.phone}>
                              {(errors.phone && errors.phone.message) || ''}
                              {(phoneInfo && strings.PHONE_INFO) || ''}
                            </FormHelperText>
                          </FormControl>
                          <FormControl fullWidth margin="dense">
                            <DatePicker
                              {...register('birthDate')}
                              ref={birthDateRef}
                              label={commonStrings.BIRTH_DATE}
                              variant="outlined"
                              required
                              onChange={(_birthDate) => {
                                if (errors.birthDate) {
                                  clearErrors('birthDate')
                                }
                                if (_birthDate) {
                                  setValue('birthDate', _birthDate, { shouldValidate: true })
                                } else {
                                  setValue('birthDate', undefined, { shouldValidate: true })
                                }
                              }}
                              language={language}
                            />
                            <FormHelperText error={!!errors.birthDate}>
                              {(errors.birthDate && errors.birthDate.message) || ''}
                            </FormHelperText>
                          </FormControl>

                          <div className="checkout-tos">
                            <table>
                              <tbody>
                                <tr>
                                  <td aria-label="tos">
                                    <Checkbox
                                      {...register('tos')}
                                      onChange={(e) => {
                                        if (e.target.checked && errors.tos) {
                                          clearErrors('tos')
                                        }
                                      }}
                                      color="primary"
                                    />
                                  </td>
                                  <td>
                                    <Link href="/tos" target="_blank" rel="noreferrer">
                                      {commonStrings.TOS}
                                    </Link>
                                  </td>
                                </tr>
                                <tr>
                                  <td colSpan={2}>
                                    <FormHelperText error={!!errors.tos}>{errors.tos?.message || ''}</FormHelperText>
                                  </td>
                                </tr>
                              </tbody>
                            </table>
                          </div>

                          <SocialLogin reloadPage />
                        </div>
                      </div>
                    )}

                    {car.supplier.licenseRequired && (
                      <div className="driver-details">
                        <div className="checkout-info">
                          <LicenseIcon />
                          <span>{commonStrings.DRIVER_LICENSE}</span>
                        </div>
                        <div className="driver-details-form">
                          <DriverLicense
                            user={user}
                            variant="outlined"
                            onUpload={(filename) => {
                              if (filename) {
                                setLicenseRequired(false)
                              } else {
                                setLicenseRequired(true)
                              }
                              setLicense(filename)
                            }}
                            onDelete={() => {
                              setLicenseRequired(false)
                              setLicense(null)
                            }}
                            hideDelete={!!clientSecret || payPalLoaded}
                          />
                        </div>
                      </div>
                    )}

                    {(adManuallyChecked && additionalDriver) && (
                      <div className="driver-details">
                        <div className="checkout-info">
                          <DriverIcon />
                          <span>{csStrings.ADDITIONAL_DRIVER}</span>
                        </div>
                        <div className="driver-details-form">
                          <FormControl fullWidth margin="dense">
                            <InputLabel className="required">{commonStrings.FULL_NAME}</InputLabel>
                            <OutlinedInput
                              {...register('additionalDriverFullName')}
                              type="text"
                              label={commonStrings.FULL_NAME}
                              required={adRequired}
                              autoComplete="off"
                            />
                          </FormControl>
                          <FormControl fullWidth margin="dense">
                            <InputLabel className="required">{commonStrings.EMAIL}</InputLabel>
                            <OutlinedInput
                              // {...register('additionalDriverEmail')}
                              inputRef={additionalDriverEmailRef}
                              value={additionalDriverEmail}
                              type="text"
                              label={commonStrings.EMAIL}
                              error={!!errors.additionalDriverEmail}
                              required={adRequired}
                              autoComplete="off"
                              onChange={(e) => {
                                if (errors.additionalDriverEmail) {
                                  clearErrors('additionalDriverEmail')
                                }
                                setValue('additionalDriverEmail', e.target.value)
                              }}
                              onBlur={() => {
                                trigger('additionalDriverEmail')
                              }}
                            />
                            <FormHelperText error={!!errors.additionalDriverEmail}>
                              {(errors.additionalDriverEmail && errors.additionalDriverEmail.message) || ''}
                            </FormHelperText>
                          </FormControl>
                          <FormControl fullWidth margin="dense">
                            <InputLabel className="required">{commonStrings.PHONE}</InputLabel>
                            <OutlinedInput
                              // {...register('additionalDriverPhone')}
                              inputRef={additionalDriverPhoneRef}
                              value={additionalDriverPhone}
                              type="text"
                              label={commonStrings.PHONE}
                              error={!!errors.additionalDriverPhone}
                              required={adRequired}
                              autoComplete="off"
                              onChange={(e) => {
                                if (errors.additionalDriverPhone) {
                                  clearErrors('additionalDriverPhone')
                                }
                                setValue('additionalDriverPhone', e.target.value)
                              }}
                              onBlur={() => {
                                trigger('additionalDriverPhone')
                              }}
                            />
                            <FormHelperText error={!!errors.additionalDriverPhone}>
                              {(errors.additionalDriverPhone && errors.additionalDriverPhone.message) || ''}
                            </FormHelperText>
                          </FormControl>
                          <FormControl fullWidth margin="dense">
                            <DatePicker
                              {...register('additionalDriverBirthDate')}
                              ref={additionalDriverBirthDateRef}
                              label={commonStrings.BIRTH_DATE}
                              variant="outlined"
                              required={adRequired}
                              onChange={(_birthDate) => {
                                if (_birthDate) {
                                  setValue('additionalDriverBirthDate', _birthDate, { shouldValidate: true })
                                } else {
                                  setValue('additionalDriverBirthDate', undefined, { shouldValidate: true })
                                }
                              }}
                              language={language}
                            />
                            <FormHelperText error={!!errors.additionalDriverBirthDate}>
                              {(errors.additionalDriverBirthDate && errors.additionalDriverBirthDate.message) || ''}
                            </FormHelperText>
                          </FormControl>
                        </div>
                      </div>
                    )}
                      </div>

                    {/* STEP 3: JazzCash / Easypaisa / Raast 20% Escrow Lock */}
                    <div className="checkout-step-section" id="checkout-step-3">
                      <div className="checkout-step-title">
                        <span className="step-badge">STEP 3</span>
                        <h2>Payment</h2>
                      </div>

                      <PakistanPayments />

                      <div className="payment-options-container">
                        <div className="checkout-info">
                          <PaymentOptionsIcon />
                          <span>{strings.PAYMENT_OPTIONS}</span>
                        </div>
                      <div className="payment-options">
                        <FormControl>
                          <RadioGroup
                            defaultValue={depositPrice > 0 ? 'payOnline' : 'payInFull'}
                            onChange={(e) => {
                              setValue('payLater', e.target.value === 'payLater')
                              setValue('payDeposit', e.target.value === 'payDeposit')
                              setValue('payInFull', e.target.value === 'payInFull')
                            }}
                          >
                            {car.supplier.payLater && (
                              <FormControlLabel
                                value="payLater"
                                control={<Radio />}
                                disabled={!!clientSecret || payPalLoaded}
                                className={clientSecret || payPalLoaded ? 'payment-radio-disabled' : ''}
                                label={(
                                  <span className="payment-button">
                                    <span>{strings.PAY_LATER}</span>
                                    <span className="payment-info">{strings.PAY_LATER_INFO}</span>
                                  </span>
                                )}
                              />
                            )}
                            {
                              car.deposit > 0 && (
                                <FormControlLabel
                                  value="payDeposit"
                                  control={<Radio />}
                                  disabled={!!clientSecret || payPalLoaded}
                                  className={clientSecret || payPalLoaded ? 'payment-radio-disabled' : ''}
                                  label={(
                                    <span className="payment-button">
                                      <span>{strings.PAY_DEPOSIT}</span>
                                      <span className="payment-info">{strings.PAY_DEPOSIT_INFO}</span>
                                    </span>
                                  )}
                                />
                              )
                            }
                            {
                              depositPrice > 0 && (
                                <FormControlLabel
                                  value="payOnline"
                                  control={<Radio />}
                                  disabled={!!clientSecret || payPalLoaded}
                                  className={clientSecret || payPalLoaded ? 'payment-radio-disabled' : ''}
                                  label={(
                                    <span className="payment-button">
                                      <span>{strings.PAY_ONLINE}</span>
                                      <span className="payment-info">{strings.PAY_ONLINE_INFO}</span>
                                    </span>
                                  )}
                                />
                              )
                            }
                            <FormControlLabel
                              value="payInFull"
                              control={<Radio />}
                              disabled={!!clientSecret || payPalLoaded}
                              className={clientSecret || payPalLoaded ? 'payment-radio-disabled' : ''}
                              label={(
                                <span className="payment-button">
                                  <span>{strings.PAY_IN_FULL}</span>
                                  <span className="payment-info">{strings.PAY_IN_FULL_INFO}</span>
                                </span>
                              )}
                            />
                          </RadioGroup>
                        </FormControl>
                      </div>
                    </div>

                    {/* Checkout checklist */}

                    <div className="checkout-details-container">
                      <div className="checkout-info">
                        <ChecklistIcon />
                        <span>{strings.PICK_UP_CHECKLIST_TITLE}</span>
                      </div>
                      <div className="checkout-details">
                        <div className="checkout-detail" style={{ height: bookingDetailHeight }}>
                          <span className="checkout-detail-title">{strings.PICK_UP_CHECKLIST_ARRIVE_ON_TIME_TITLE}</span>
                          <div className="checkout-detail-value checklist-content">
                            {strings.PICK_UP_CHECKLIST_ARRIVE_ON_TIME_CONTENT}
                          </div>
                        </div>
                        <div className="checkout-detail" style={{ height: bookingDetailHeight }}>
                          <span className="checkout-detail-title">{strings.PICK_UP_CHECKLIST_DOCUMENTS_TITLE}</span>
                          <div className="checkout-detail-value checklist-content">
                            {strings.PICK_UP_CHECKLIST_DOCUMENTS_CONTENT}
                          </div>
                        </div>
                      </div>
                    </div>

                    {/* Total price */}

                    <div className="payment-info">
                      <div className="payment-info-title">
                        {
                          payDeposit ? strings.DEPOSIT : `${strings.PRICE_FOR} ${days} ${days > 1 ? strings.DAYS : strings.DAY}`
                        }
                      </div>
                      <div className="payment-info-price">
                        {
                          bookcarsHelper.formatPrice(
                            payDeposit ? depositPrice
                              : payInFull ? (price + depositPrice)
                                : price
                            , commonStrings.CURRENCY, language)
                        }
                      </div>
                    </div>
                    {quote && (
                      <div className="checkout-price-breakdown" aria-label="Itemized PKR quote">
                        <div><span>Base rent</span><strong>{bookcarsHelper.formatPrice(quote.baseRentPKR, 'PKR', language)}</strong></div>
                        <div><span>Driver allowance</span><strong>{bookcarsHelper.formatPrice(quote.driverAllowancePKR, 'PKR', language)}</strong></div>
                        <div><span>Inter-city / northern surcharge</span><strong>{bookcarsHelper.formatPrice(quote.outOfCitySurchargePKR, 'PKR', language)}</strong></div>
                        <div><span>Security deposit</span><strong>{bookcarsHelper.formatPrice(quote.securityDepositPKR, 'PKR', language)}</strong></div>
                        <div className="checkout-price-breakdown-total"><span>Total payable</span><strong>{bookcarsHelper.formatPrice(quote.totalPayablePKR, 'PKR', language)}</strong></div>
                      </div>
                    )}

                    {!onlinePaymentConfigured && !car.supplier.payLater && (
                      <Alert severity="info" sx={{ my: 2, color: '#f5f5f7', bgcolor: '#24211a', border: '1px solid rgba(212,175,55,.4)' }}>
                        Online checkout is unavailable until a payment provider is connected. Please contact the rental supplier to arrange payment.
                      </Alert>
                    )}

                    {(!car.supplier.payLater || !payLater) && (
                      env.PAYMENT_GATEWAY === bookcarsTypes.PaymentGateway.Stripe
                        ? (
                          clientSecret && (
                            <div className="payment-options-container">
                              <EmbeddedCheckoutProvider
                                stripe={stripePromise}
                                options={{ clientSecret }}
                              >
                                <EmbeddedCheckout />
                              </EmbeddedCheckoutProvider>
                            </div>
                          )
                        )
                        : payPalLoaded ? (
                          <div className="payment-options-container">
                            <PayPalButtons
                              createOrder={async () => {
                                try {
                                  if (!bookingId) {
                                    console.error('Missing bookingId before PayPal order creation')
                                    return ''
                                  }
                                  const name = bookcarsHelper.truncateString(car.name, PayPalService.ORDER_NAME_MAX_LENGTH)
                                  const _description = `${car.name} - ${daysLabel} - ${pickupLocation._id === dropOffLocation._id ? pickupLocation.name : `${pickupLocation.name} - ${dropOffLocation.name}`}`
                                  const description = bookcarsHelper.truncateString(_description, PayPalService.ORDER_DESCRIPTION_MAX_LENGTH)
                                  const orderId = await PayPalService.createOrder(bookingId!, basePaymentAmount, env.BASE_CURRENCY, name, description)
                                  return orderId || ''
                                } catch (err) {
                                  console.error('Error creating PayPal order', err)
                                  return ''
                                }
                              }}
                              onApprove={async (data, actions) => {
                                try {
                                  setPayPalProcessing(true)
                                  await actions.order?.capture()
                                  const { orderID } = data
                                  const status = await PayPalService.checkOrder(bookingId!, orderID)

                                  if (status === 200) {
                                    setVisible(false)
                                    setSuccess(true)
                                  } else {
                                    setPaymentFailed(true)
                                  }
                                } catch (err) {
                                  helper.error(err)
                                } finally {
                                  setPayPalProcessing(false)
                                }
                              }}
                              onInit={() => {
                                setPayPalInit(true)
                              }}
                              onCancel={() => {
                                setPayPalProcessing(false)
                              }}
                              onError={() => {
                                setPayPalProcessing(false)
                              }}
                            />
                          </div>
                        ) : null
                    )}
                    <div className="checkout-buttons">
                      {(
                        (onlinePaymentConfigured && env.PAYMENT_GATEWAY === bookcarsTypes.PaymentGateway.Stripe && !clientSecret)
                        || (onlinePaymentConfigured && env.PAYMENT_GATEWAY === bookcarsTypes.PaymentGateway.PayPal && !payPalInit)
                        || payLater) && (
                          <Button
                            type="submit"
                            variant="contained"
                            className="btn-checkout btn-margin-bottom"
                            aria-label="Checkout"
                            disabled={isSubmitting || (payPalLoaded && !payPalInit) || (!onlinePaymentConfigured && !payLater)}
                          >
                            {
                              (isSubmitting || (payPalLoaded && !payPalInit))
                                ? <CircularProgress color="inherit" size={24} />
                                : strings.BOOK
                            }
                          </Button>
                        )}
                      <Button
                        variant="outlined"
                        color="primary"
                        className="btn-cancel btn-margin-bottom"
                        aria-label="Cancel"
                        onClick={async () => {
                          try {
                            if (bookingId && sessionId) {
                              //
                              // Delete temporary booking on cancel.
                              // Otherwise, temporary bookings are
                              // automatically deleted through a TTL index.
                              //
                              await BookingService.deleteTempBooking(bookingId, sessionId)
                            }
                            if (!authenticated && license) {
                              await UserService.deleteTempLicense(license)
                            }
                          } catch (err) {
                            helper.error(err)
                          } finally {
                            navigate('/')
                          }
                        }}
                      >
                        {commonStrings.CANCEL}
                      </Button>
                    </div>
                    </div>
                  </div>
                  <div className="form-error">
                    {paymentFailed && <Error message={strings.PAYMENT_FAILED} />}
                    {recaptchaError && <Error message={commonStrings.RECAPTCHA_ERROR} />}
                    {licenseRequired && <Error message={strings.LICENSE_REQUIRED} />}
                  </div>
                </form>
              </Paper>
            </div>

            <aside className="checkout-fare-sidebar">
              <div className="fare-sidebar-card">
                <div className="fare-vehicle-preview">
                  {car.image && env.CDN_CARS ? (
                    <img
                      src={bookcarsHelper.joinURL(env.CDN_CARS, car.image)}
                      alt={car.name}
                      className="fare-vehicle-img"
                    />
                  ) : (
                    <div className="fare-vehicle-placeholder">🚗</div>
                  )}
                  <div className="fare-vehicle-info">
                    <h3 className="fare-vehicle-name">{car.name}</h3>
                    <span className="fare-supplier-tag">{car.supplier?.fullName || 'Rental supplier'}</span>
                  </div>
                </div>

                <div className="fare-trip-route">
                  <div className="fare-route-point">
                    <span className="route-dot start"></span>
                    <div className="route-details">
                      <span className="route-type">PICKUP HUB</span>
                      <span className="route-name">{pickupLocation.name}</span>
                      <span className="route-time">{from && format(from, 'eee, d MMM yyyy, p')}</span>
                    </div>
                  </div>
                  <div className="fare-route-line"></div>
                  <div className="fare-route-point">
                    <span className="route-dot end"></span>
                    <div className="route-details">
                      <span className="route-type">DROP-OFF HUB</span>
                      <span className="route-name">{dropOffLocation.name}</span>
                      <span className="route-time">{to && format(to, 'eee, d MMM yyyy, p')}</span>
                    </div>
                  </div>
                </div>

                <div className="fare-breakdown-box">
                  <div className="fare-breakdown-title">Itemized Fare Breakdown</div>
                  <div className="fare-row">
                    <span>Base Rent ({days} {days > 1 ? 'days' : 'day'})</span>
                    <strong className="tabular-nums pkr-price">{bookcarsHelper.formatPrice(quote?.baseRentPKR || price, 'PKR', language)}</strong>
                  </div>
                  {quote && quote.driverAllowancePKR > 0 && (
                    <div className="fare-row">
                      <span>Chauffeur Daily Allowance</span>
                      <strong className="tabular-nums pkr-price">{bookcarsHelper.formatPrice(quote.driverAllowancePKR, 'PKR', language)}</strong>
                    </div>
                  )}
                  {quote && quote.outOfCitySurchargePKR > 0 && (
                    <div className="fare-row">
                      <span>Inter-City / Northern Surcharge</span>
                      <strong className="tabular-nums pkr-price">{bookcarsHelper.formatPrice(quote.outOfCitySurchargePKR, 'PKR', language)}</strong>
                    </div>
                  )}
                  <div className="fare-row">
                    <span>Refundable Security Deposit</span>
                    <strong className="tabular-nums pkr-price">{bookcarsHelper.formatPrice(depositPrice, 'PKR', language)}</strong>
                  </div>
                  <div className="fare-divider"></div>
                  <div className="fare-row fare-total-row">
                    <span>Total Payable</span>
                    <strong className="tabular-nums pkr-price">{bookcarsHelper.formatPrice(fareTotal, 'PKR', language)}</strong>
                  </div>
                  {env.FYP_DEMO_MODE && (
                    <div className="fare-escrow-split" aria-label="Illustrative payment schedule">
                      <div className="escrow-split-box now">
                        <span className="escrow-split-label">Demo advance · 20%</span>
                        <strong className="escrow-split-amount pkr-price">{bookcarsHelper.formatPrice(demoAdvance, 'PKR', language)}</strong>
                      </div>
                      <div className="escrow-split-box handover">
                        <span className="escrow-split-label">Demo handover balance · 80%</span>
                        <strong className="escrow-split-amount pkr-price">{bookcarsHelper.formatPrice(fareTotal - demoAdvance, 'PKR', language)}</strong>
                      </div>
                    </div>
                  )}
                </div>
              </div>
            </aside>
          </div>

            <Footer />
          </>
        )}

        {user?.blacklisted && <Unauthorized />}

        {noMatch && <NoMatch hideHeader />}

        {success && bookingId && (
          <CheckoutStatus
            bookingId={bookingId}
            language={language}
            payLater={payLater}
            sessionId={sessionId}
            status="success"
            className="status"
          />
        )}

        {payPalProcessing && <Backdrop text={strings.CHECKING} />}

        <MapDialog
          pickupLocation={pickupLocation}
          openMapDialog={openMapDialog}
          onClose={() => setOpenMapDialog(false)}
        />
      </Layout>

      {loadingPage && !noMatch && <Progress />}
    </>
  )
}

export default Checkout

import React, { useState } from 'react'
import { useNavigate } from 'react-router-dom'
import { useForm } from 'react-hook-form'
import { zodResolver } from '@hookform/resolvers/zod'
import {
  Input,
  InputLabel,
  FormControl,
  FormHelperText,
  Button,
  Paper,
  Box,
  Typography,
  Alert
} from '@mui/material'
import {
  VpnKey as KeyIcon,
  CheckCircle as SuccessIcon,
  ArrowBack as BackIcon
} from '@mui/icons-material'
import * as bookcarsTypes from ':bookcars-types'
import * as UserService from '@/services/UserService'
import Layout from '@/components/Layout'
import { strings as commonStrings } from '@/lang/common'
import { strings } from '@/lang/reset-password'
import SocialLogin from '@/components/SocialLogin'
import Footer from '@/components/Footer'
import SafarRentLogo from '@/components/SafarRentLogo'
import * as helper from '@/utils/helper'
import { schema, FormFields } from '@/models/ForgotPasswordForm'

import '@/assets/css/forgot-password.css'

const ForgotPassword = () => {
  const navigate = useNavigate()

  const [visible, setVisible] = useState(false)
  const [sent, setSent] = useState(false)

  const {
    register,
    handleSubmit,
    formState: { errors, isSubmitting },
    clearErrors,
  } = useForm({
    resolver: zodResolver(schema),
    mode: 'onSubmit',
  })

  const onLoad = (user?: bookcarsTypes.User) => {
    if (user) {
      navigate('/')
    } else {
      setVisible(true)
    }
  }

  const onSubmit = async ({ email }: FormFields) => {
    try {
      const status = await UserService.resend(email, true)
      if (status === 200) {
        setSent(true)
      } else {
        helper.error()
      }
    } catch (err) {
      helper.error(err)
    }
  }

  return (
    <Layout onLoad={onLoad} strict={false}>
      <Box
        className="forgot-password"
        sx={{
          minHeight: '80vh',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          py: 6,
          px: 2,
          background: 'linear-gradient(180deg, rgba(11, 17, 32, 0.03) 0%, transparent 100%)'
        }}
      >
        <Paper
          elevation={12}
          sx={{
            width: '100%',
            maxWidth: 460,
            borderRadius: '20px',
            p: { xs: 3, sm: 4.5 },
            border: '1px solid var(--sr-border, #E2E8F0)',
            background: 'var(--sr-surface, #FFFFFF)',
            boxShadow: '0 20px 40px rgba(11, 17, 32, 0.08)',
            display: visible ? 'block' : 'none'
          }}
        >
          {/* Header Icon & Brand */}
          <Box sx={{ textAlign: 'center', mb: 3 }}>
            <Box
              sx={{
                width: 56,
                height: 56,
                borderRadius: '16px',
                bgcolor: 'rgba(5, 150, 105, 0.1)',
                color: 'var(--sr-emerald)',
                display: 'inline-flex',
                alignItems: 'center',
                justifyContent: 'center',
                mb: 2
              }}
            >
              <KeyIcon sx={{ fontSize: 30 }} />
            </Box>
            <Typography variant="h5" sx={{ fontWeight: 800, color: 'var(--sr-text, #0B1120)', letterSpacing: '-0.02em', mb: 0.5 }}>
              {strings.RESET_PASSWORD_HEADING}
            </Typography>
            <Typography variant="body2" color="text.secondary">
              Enter your registered email address and we will send you a secure link to reset your password.
            </Typography>
          </Box>

          {!sent ? (
            <form onSubmit={handleSubmit(onSubmit)}>
              <FormControl fullWidth margin="dense" sx={{ mb: 2 }}>
                <InputLabel className="required">{commonStrings.EMAIL}</InputLabel>
                <Input
                  {...register('email')}
                  onChange={() => {
                    if (errors.email) {
                      clearErrors('email')
                    }
                  }}
                  type="email"
                  error={!!errors.email}
                  autoComplete="off"
                  required
                />
                <FormHelperText error={!!errors.email}>
                  {errors.email?.message || ''}
                </FormHelperText>
              </FormControl>

              <SocialLogin redirectToHomepage />

              <Box sx={{ display: 'flex', flexDirection: 'column', gap: 1.5, mt: 3 }}>
                <Button
                  type="submit"
                  className="btn-primary"
                  variant="contained"
                  disabled={isSubmitting}
                  sx={{
                    bgcolor: '#107487',
                    '&:hover': { bgcolor: '#047857' },
                    fontWeight: 700,
                    py: 1.2,
                    textTransform: 'none',
                    borderRadius: '10px'
                  }}
                >
                  {strings.RESET}
                </Button>
                <Button
                  variant="outlined"
                  onClick={() => navigate('/sign-in')}
                  startIcon={<BackIcon />}
                  sx={{
                    textTransform: 'none',
                    borderRadius: '10px',
                    borderColor: 'var(--sr-border, #CBD5E1)',
                    color: 'var(--sr-text, #334155)'
                  }}
                >
                  Return to Sign In
                </Button>
              </Box>
            </form>
          ) : (
            <Box sx={{ textAlign: 'center', py: 2 }}>
              <Alert severity="success" icon={<SuccessIcon sx={{ color: 'var(--sr-emerald)' }} />} sx={{ mb: 3, borderRadius: '12px' }}>
                {strings.EMAIL_SENT}
              </Alert>
              <Typography variant="body2" color="text.secondary" sx={{ mb: 3 }}>
                Check your spam or junk folder if you don&apos;t see the email within 2 minutes.
              </Typography>
              <Button
                variant="contained"
                onClick={() => navigate('/')}
                sx={{
                  bgcolor: '#107487',
                  '&:hover': { bgcolor: '#047857' },
                  fontWeight: 700,
                  textTransform: 'none',
                  borderRadius: '10px',
                  width: '100%',
                  py: 1.2
                }}
              >
                {commonStrings.GO_TO_HOME}
              </Button>
            </Box>
          )}
        </Paper>
      </Box>

      <Footer />
    </Layout>
  )
}

export default ForgotPassword

import React, { useEffect, useState } from 'react'
import { useNavigate } from 'react-router-dom'
import {
  Button,
  Alert,
  CircularProgress,
  TextField,
  // Checkbox,
  Dialog,
  DialogContent,
  // FormControlLabel,
  Tab,
  Tabs,
  Chip,
  Box,
  Typography
} from '@mui/material'
import {
  RoomService,
  VisibilityOff,
  DirectionsCar,
  Speed,
  Navigation,
  AttachMoney,
  Public,
  FlashOn,
  CheckBox,
  AutoAwesome as AutoAwesomeIcon,
  Search as SearchIcon,
  VerifiedUser as ShieldIcon,
  AccountBalanceWallet as WalletIcon,
  CameraAlt as CameraIcon,
  Terrain as TerrainIcon,
  ArrowForward as ArrowForwardIcon,
} from '@mui/icons-material'
import L from 'leaflet'
import * as bookcarsTypes from ':bookcars-types'
import * as bookcarsHelper from ':bookcars-helper'
import env from '@/config/env.config'
import { strings as carsStrings } from '@/lang/cars'
import { strings } from '@/lang/home'
import * as SupplierService from '@/services/SupplierService'
import * as CountryService from '@/services/CountryService'
import * as LocationService from '@/services/LocationService'
import Layout from '@/components/Layout'
import SupplierCarrousel from '@/components/SupplierCarrousel'
