import Layout from '@/components/Layout'
import Map from '@/components/Map'
import SearchForm from '@/components/SearchForm'
import Footer from '@/components/Footer'

import '@/assets/css/locations.css'

interface FeaturedHub {
  id: string
  name: string
  city: string
  tag: string
  fleetCount: string
  address: string
  hours: string
  icon: 'mountain' | 'city'
}

const FEATURED_HUBS: FeaturedHub[] = [
  {
    id: 'isb-blue-area',
    name: 'Blue Area Central Hub',
    city: 'Islamabad',
    tag: 'Northern Gateway',
    fleetCount: '28+ Vehicles',
    address: 'Jinnah Avenue, Blue Area, Islamabad',
    hours: '24/7 Escrow Dispatch',
    icon: 'city'
  },
  {
    id: 'lhr-gulberg',
    name: 'Gulberg Executive Hub',
    city: 'Lahore',
    tag: 'Executive & Chauffeur',
    fleetCount: '35+ Vehicles',
    address: 'Main Boulevard, Gulberg III, Lahore',
    hours: '24/7 Escrow Dispatch',
    icon: 'city'
  },
  {
    id: 'swl-high-street',
    name: 'High Street Hub',
    city: 'Sahiwal',
    tag: 'Central Punjab',
    fleetCount: '18+ Vehicles',
    address: 'High Street, Near Stadium, Sahiwal',
    hours: '08:00 AM – 11:00 PM',
    icon: 'city'
  },
  {
    id: 'murree-express',
    name: 'Expressway & Hills Hub',
    city: 'Murree',
    tag: '4x4 Hill Route Approved',
    fleetCount: '15+ SUVs',
    address: 'Lower Topa / Murree Expressway Junction',
    hours: '24/7 Outstation & Delivery',
    icon: 'mountain'
  }
]

const Locations = () => {
  const navigate = useNavigate()
  const [locations, setLocations] = useState<bookcarsTypes.Location[]>([])
  const [pickupLocation, setPickupLocation] = useState('')
  const [openSearchFormDialog, setOpenSearchFormDialog] = useState(false)

  const onLoad = async () => {
    const _locations = await LocationService.getLocationsWithPosition()
    setLocations(_locations)
  }

  const handleBrowseHub = (hub: FeaturedHub) => {
    const matched = locations.find((l) => (l.name || '').toLowerCase().includes(hub.city.toLowerCase()))
    if (matched && matched._id) {
      setPickupLocation(matched._id)
      setOpenSearchFormDialog(true)
    } else {
      navigate('/search')
    }
  }

  return (
    <Layout onLoad={onLoad} strict={false}>
      <Box sx={{ maxWidth: 1400, mx: 'auto', px: { xs: 2, sm: 3 }, py: 4 }}>
        {/* Page Header */}
        <Box sx={{ mb: 3 }}>
          <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, mb: 0.5 }}>
            <LocationIcon sx={{ color: 'var(--sr-emerald)', fontSize: 18 }} />
            <Typography sx={{ color: 'var(--sr-emerald)', fontWeight: 800, fontSize: 11, letterSpacing: '0.08em', textTransform: 'uppercase' }}>
              SafarRent • Strategic Mobility Corridors
            </Typography>
          </Box>
          <Typography variant="h4" sx={{ fontWeight: 800, color: 'var(--sr-text, #0B1120)', letterSpacing: '-0.02em', mb: 1 }}>
            Pickup Hubs & Vehicle Dispatch Points
          </Typography>
          <Typography color="text.secondary" sx={{ fontSize: 14 }}>
            Explore verified handover points across Islamabad, Lahore, Sahiwal, and Murree. Select any hub on the interactive map or browse available fleet below.
          </Typography>
        </Box>

        {/* Split-View: Map + Hub Cards */}
        <Box sx={{ display: 'grid', gridTemplateColumns: { xs: '1fr', lg: '1fr 380px' }, gap: 3, mb: 4 }}>
          {/* Interactive Map Pane */}
          <Box
            sx={{
              height: { xs: 360, lg: 540 },
              borderRadius: '20px',
              overflow: 'hidden',
              border: '1px solid var(--sr-border, #E2E8F0)',
              boxShadow: '0 8px 24px rgba(11, 17, 32, 0.05)',
              position: 'relative'
            }}
          >
            <Map
              position={new L.LatLng(env.MAP_LATITUDE, env.MAP_LONGITUDE)}
              initialZoom={env.MAP_ZOOM}
              locations={locations}
              onSelelectPickUpLocation={async (locationId) => {
                setPickupLocation(locationId)
                setOpenSearchFormDialog(true)
              }}
            />
          </Box>

          {/* Quick Hub Quick-Select List */}
          <Box sx={{ display: 'flex', flexDirection: 'column', gap: 2, maxHeight: { lg: 540 }, overflowY: 'auto' }}>
            <Typography variant="subtitle2" sx={{ fontWeight: 800, color: 'var(--sr-text, #0B1120)', letterSpacing: '-0.01em' }}>
              Active Mobility Corridors
            </Typography>
            {FEATURED_HUBS.map((hub) => (
              <Card
                key={hub.id}
                sx={{
                  borderRadius: '14px',
                  border: '1px solid var(--sr-border, #E2E8F0)',
                  bgcolor: 'var(--sr-surface, #FFFFFF)',
                  boxShadow: '0 2px 8px rgba(0,0,0,0.03)',
                  transition: 'transform 0.2s ease, border-color 0.2s ease',
                  '&:hover': {
                    borderColor: '#059669',
                    transform: 'translateY(-2px)'
                  }
                }}
              >
                <CardContent sx={{ p: 2 }}>
                  <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', mb: 1 }}>
                    <Box>
                      <Typography variant="subtitle2" sx={{ fontWeight: 800, color: 'var(--sr-text, #0B1120)' }}>
                        {hub.name}
                      </Typography>
                      <Typography variant="caption" color="text.secondary">
                        {hub.address}
                      </Typography>
                    </Box>
                    <Chip
                      label={hub.tag}
                      size="small"
                      sx={{
                        fontSize: 9,
                        fontWeight: 700,
                        bgcolor: hub.icon === 'mountain' ? 'rgba(217, 119, 6, 0.1)' : 'rgba(5, 150, 105, 0.1)',
                        color: hub.icon === 'mountain' ? 'var(--sr-accent-text)' : 'var(--sr-emerald)',
                        height: 20
                      }}
                    />
                  </Box>

                  <Box sx={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', mt: 1.5, pt: 1, borderTop: '1px solid rgba(0,0,0,0.05)' }}>
                    <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                      <Chip
                        icon={<CarIcon sx={{ fontSize: '12px !important' }} />}
                        label={hub.fleetCount}
                        size="small"
                        sx={{ fontSize: 10, fontWeight: 700, fontFamily: 'var(--sr-font-mono, monospace)', height: 20 }}
                      />
                      <Typography variant="caption" color="text.secondary" sx={{ fontSize: 10 }}>
                        {hub.hours}
                      </Typography>
                    </Box>
                    <Button
                      size="small"
                      variant="text"
                      endIcon={<SearchIcon sx={{ fontSize: '14px !important' }} />}
                      onClick={() => handleBrowseHub(hub)}
                      sx={{ color: 'var(--sr-emerald)', fontWeight: 700, fontSize: 11, textTransform: 'none', p: 0.5 }}
                    >
                      Browse Cars
                    </Button>
                  </Box>
                </CardContent>
              </Card>
            ))}
          </Box>
        </Box>
      </Box>

      {/* Search Form Modal for Hub selection */}
      <Dialog
        fullWidth={env.isMobile}
        maxWidth={false}
        open={openSearchFormDialog}
        onClose={() => setOpenSearchFormDialog(false)}
      >
        <DialogContent className="search-dialog-content">
          <SearchForm
            ranges={bookcarsHelper.getAllRanges()}
            pickupLocation={pickupLocation}
            onCancel={() => setOpenSearchFormDialog(false)}
          />
        </DialogContent>
      </Dialog>

      <Footer />
    </Layout>
  )
}

export default Locations

import React, { useState } from 'react'
import { useNavigate } from 'react-router-dom'
import {
  Button,
  Paper,
  Box,
  Typography
} from '@mui/material'
import {
  VpnKey as KeyIcon,
  LockReset as ResetIcon
} from '@mui/icons-material'
import { useForm } from 'react-hook-form'
import { zodResolver } from '@hookform/resolvers/zod'
import * as bookcarsTypes from ':bookcars-types'
import * as UserService from '@/services/UserService'
import Layout from '@/components/Layout'
import { strings as commonStrings } from '@/lang/common'
import { strings as rpStrings } from '@/lang/reset-password'
import { useUserContext, UserContextType } from '@/context/UserContext'
import * as helper from '@/utils/helper'
import Error from './Error'
import NoMatch from './NoMatch'
import Footer from '@/components/Footer'
import { schema, FormFields } from '@/models/ResetPasswordForm'

import '@/assets/css/reset-password.css'
import PasswordInput from '@/components/PasswordInput'

const ResetPassword = () => {
  const navigate = useNavigate()

  const { setUser, setUserLoaded } = useUserContext() as UserContextType
  const [userId, setUserId] = useState('')
  const [email, setEmail] = useState('')
  const [token, setToken] = useState('')
  const [visible, setVisible] = useState(false)
  const [noMatch, setNoMatch] = useState(false)
  const [isAuthenticated, setIsAuthenticated] = useState(false)

  const { register, handleSubmit, formState: { errors, isSubmitting }, setValue, setError, clearErrors } = useForm<FormFields>({
    resolver: zodResolver(schema),
    mode: 'onSubmit',
  })

  const onSubmit = async ({ password }: FormFields) => {
    try {
      const data: bookcarsTypes.ActivatePayload = { userId, token, password }

      const status = await UserService.activate(data)

      if (status === 200) {
        const signInResult = await UserService.signin({ email, password })

        if (signInResult.status === 200) {
          const user = await UserService.getUser(signInResult.data._id)
          setIsAuthenticated(true)
          setUser(user)
          setUserLoaded(true)

          const _status = await UserService.deleteTokens(userId)

          if (_status === 200) {
            navigate('/')
          } else {
            helper.error()
          }
        } else {
          helper.error()
        }
      } else {
        helper.error()
      }
    } catch (err) {
      helper.error(err)
    }
  }

  const onLoad = async (user?: bookcarsTypes.User) => {
    if (user) {
      setNoMatch(true)
    } else {
      const params = new URLSearchParams(window.location.search)
      if (params.has('u') && params.has('e') && params.has('t')) {
        const _userId = params.get('u')
        const _email = params.get('e')
        const _token = params.get('t')
        if (_userId && _email && _token) {
          try {
            const status = await UserService.checkToken(_userId, _email, _token)

            if (status === 200) {
              setUserId(_userId)
              setEmail(_email)
              setToken(_token)
              setVisible(true)
            } else {
              setNoMatch(true)
            }
          } catch (err) {
            console.error(err)
            setError('root', {})
          }
        } else {
          setNoMatch(true)
        }
      } else {
        setNoMatch(true)
      }
    }
  }

  return (
    <Layout onLoad={onLoad} strict={false}>
      <div className={visible ? '' : 'hidden'}>
        <Box
          className="reset-password"
          sx={{
            minHeight: '80vh',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            py: 6,
            px: 2,
            background: 'linear-gradient(180deg, rgba(11, 17, 32, 0.03) 0%, transparent 100%)'
          }}
        >
          <Paper
            elevation={12}
            sx={{
              width: '100%',
              maxWidth: 460,
              borderRadius: '20px',
              p: { xs: 3, sm: 4.5 },
              border: '1px solid var(--sr-border, #E2E8F0)',
              background: 'var(--sr-surface, #FFFFFF)',
              boxShadow: '0 20px 40px rgba(11, 17, 32, 0.08)'
            }}
          >
            {/* Header Icon */}
            <Box sx={{ textAlign: 'center', mb: 3 }}>
              <Box
                sx={{
                  width: 56,
                  height: 56,
                  borderRadius: '16px',
                  bgcolor: 'rgba(5, 150, 105, 0.1)',
                  color: 'var(--sr-emerald)',
                  display: 'inline-flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                  mb: 2
                }}
              >
                <ResetIcon sx={{ fontSize: 30 }} />
              </Box>
              <Typography variant="h5" sx={{ fontWeight: 800, color: 'var(--sr-text, #0B1120)', letterSpacing: '-0.02em', mb: 0.5 }}>
                {rpStrings.RESET_PASSWORD_HEADING}
              </Typography>
              <Typography variant="body2" color="text.secondary">
                Choose a strong, unique password with at least 6 characters.
              </Typography>
            </Box>

            <form onSubmit={handleSubmit(onSubmit)}>
              <PasswordInput
                label={commonStrings.PASSWORD}
                variant="standard"
                {...register('password')}
                error={!!errors.password}
                helperText={errors.password?.message}
                onChange={(e) => {
                  if (errors.password) {
                    clearErrors('password')
                  }
                  setValue('password', e.target.value)
                }}
                required
                autoComplete="new-password"
              />

              <PasswordInput
                label={commonStrings.CONFIRM_PASSWORD}
                variant="standard"
                {...register('confirmPassword')}
                error={!!errors.confirmPassword}
                helperText={errors.confirmPassword?.message}
                onChange={(e) => {
                  if (errors.confirmPassword) {
                    clearErrors('confirmPassword')
                  }
                  setValue('confirmPassword', e.target.value)
                }}
                required
                inputProps={{
                  autoComplete: 'new-password',
                  form: {
                    autoComplete: 'off',
                  },
                }}
              />

              <Box sx={{ display: 'flex', flexDirection: 'column', gap: 1.5, mt: 3.5 }}>
                <Button
                  type="submit"
                  className="btn-primary"
                  variant="contained"
                  disabled={isSubmitting}
                  sx={{
                    bgcolor: '#107487',
                    '&:hover': { bgcolor: '#047857' },
                    fontWeight: 700,
                    py: 1.2,
                    textTransform: 'none',
                    borderRadius: '10px'
                  }}
                >
                  {commonStrings.SAVE}
                </Button>
                <Button
                  variant="outlined"
                  onClick={() => navigate('/')}
                  sx={{
                    textTransform: 'none',
                    borderRadius: '10px',
                    borderColor: 'var(--sr-border, #CBD5E1)',
                    color: 'var(--sr-text, #334155)'
                  }}
                >
                  {commonStrings.CANCEL}
                </Button>
              </Box>
            </form>
          </Paper>
        </Box>

        <Footer />
      </div>

      {errors.root && <Error />}

      {!isAuthenticated && noMatch && <NoMatch hideHeader />}
    </Layout>
  )
}

export default ResetPassword

import React, { useState } from 'react'
import { useNavigate } from 'react-router-dom'
import {
  Input,
  InputLabel,
  FormHelperText,
  FormControl,
  FormControlLabel,
  Switch,
  Button,
  Paper,
  Box,
  Tabs,
  Tab,
  Chip,
  Typography,
  Divider
} from '@mui/material'
import {
  Person as PersonIcon,
  VerifiedUser as KycIcon,
  Lock as SecurityIcon,
  CheckCircle as VerifiedIcon,
  WarningAmber as WarningIcon,
  Shield as ShieldIcon,
  VpnKey as KeyIcon
} from '@mui/icons-material'
import { useForm, useWatch } from 'react-hook-form'
import { zodResolver } from '@hookform/resolvers/zod'
import * as bookcarsTypes from ':bookcars-types'
import * as bookcarsHelper from ':bookcars-helper'
import Layout from '@/components/Layout'
import { strings as commonStrings } from '@/lang/common'
import { strings } from '@/lang/settings'
import * as UserService from '@/services/UserService'
import Backdrop from '@/components/SimpleBackdrop'
import DatePicker from '@/components/DatePicker'
import Avatar from '@/components/Avatar'
import * as helper from '@/utils/helper'
import DriverLicense from '@/components/DriverLicense'
import Footer from '@/components/Footer'
import { useUserContext, UserContextType } from '@/context/UserContext'
import { schema, FormFields } from '@/models/SettingsForm'

import '@/assets/css/settings.css'

const Settings = () => {
  const navigate = useNavigate()

  const { user, setUser } = useUserContext() as UserContextType
  const [visible, setVisible] = useState(false)
  const [loading, setLoading] = useState(true)
  const [enableEmailNotifications, setEnableEmailNotifications] = useState(false)
  const [activeTab, setActiveTab] = useState(0)

  const { register, control, handleSubmit, formState: { errors, isSubmitting }, clearErrors, setValue } = useForm<FormFields>({
    resolver: zodResolver(schema),
    mode: 'onSubmit',
  })

  const birthDate = useWatch({ control, name: 'birthDate' })

  const handleEmailNotificationsChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    try {
      if (user && user._id) {
        const _user = bookcarsHelper.clone(user) as bookcarsTypes.User
        setEnableEmailNotifications(e.target.checked)

        _user.enableEmailNotifications = e.target.checked

        const payload: bookcarsTypes.UpdateEmailNotificationsPayload = {
          _id: user._id,
          enableEmailNotifications: _user.enableEmailNotifications
        }
        const status = await UserService.updateEmailNotifications(payload)

        if (status === 200) {
          setUser(_user)
          helper.info(strings.SETTINGS_UPDATED)
        }
      } else {
        helper.error()
      }
    } catch (err) {
      helper.error(err)
    }
  }

  const onBeforeUpload = () => {
    setLoading(true)
  }

  const onAvatarChange = (_user: bookcarsTypes.User) => {
    setUser(_user)
    setLoading(false)
  }

  const onSubmit = async (data: FormFields) => {
    try {
      if (!user || !user._id) {
        return
      }

      const payload: bookcarsTypes.UpdateUserPayload = {
        _id: user._id,
        fullName: data.fullName,
        birthDate: data.birthDate,
        phone: data.phone,
        location: data.location || '',
        bio: data.bio || '',
        cnicNumber: data.cnicNumber || '',
        drivingLicenseNumber: data.drivingLicenseNumber || '',
      }

      const status = await UserService.updateUser(payload)

      if (status === 200) {
        setUser({
          ...user,
          fullName: data.fullName,
          phone: data.phone,
          birthDate: data.birthDate,
          location: data.location || undefined,
          bio: data.bio || undefined,
          cnicNumber: data.cnicNumber || undefined,
          drivingLicenseNumber: data.drivingLicenseNumber || undefined,
          kycStatus: data.cnicNumber ? bookcarsTypes.KycStatus.Pending : bookcarsTypes.KycStatus.Unverified,
        })
        helper.info(strings.SETTINGS_UPDATED)
      } else {
        helper.error()
      }
    } catch (err) {
      helper.error(err)
    }
  }

  const onLoad = (_user?: bookcarsTypes.User) => {
    if (_user) {
      setUser(_user)
      setValue('email', _user.email!)
      setValue('fullName', _user.fullName)
      setValue('phone', _user.phone || '')
      setValue('birthDate', new Date(_user.birthDate!))
      setValue('location', _user.location || '')
      setValue('bio', _user.bio || '')
      setValue('cnicNumber', _user.cnicNumber || '')
      setValue('drivingLicenseNumber', _user.drivingLicenseNumber || '')
      setEnableEmailNotifications(_user.enableEmailNotifications ?? true)
      setVisible(true)
      setLoading(false)
    }
  }

  const isKycVerified = user?.kycStatus === bookcarsTypes.KycStatus.Verified

  return (
    <Layout onLoad={onLoad} strict>
      {visible && user && (
        <>
          <div className="settings" style={{ maxWidth: 960, margin: '0 auto', padding: '32px 16px 64px' }}>
            {/* Header */}
            <Box sx={{ mb: 3 }}>
              <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, mb: 0.5 }}>
                <ShieldIcon sx={{ color: 'var(--sr-emerald)', fontSize: 18 }} />
                <Typography sx={{ color: 'var(--sr-emerald)', fontWeight: 800, fontSize: 11, letterSpacing: '0.08em', textTransform: 'uppercase' }}>
                  SafarRent • Account & Trust Settings
                </Typography>
              </Box>
              <Typography variant="h4" sx={{ fontWeight: 800, color: 'var(--sr-text, #0B1120)', letterSpacing: '-0.02em', mb: 1 }}>
                Account Settings & KYC Vault
              </Typography>
              <Typography color="text.secondary" sx={{ fontSize: 14 }}>
                Manage your profile, verified Pakistani CNIC identity, driving credentials, and security settings.
              </Typography>
            </Box>

            {/* Tab Navigation */}
            <Paper sx={{ mb: 3, borderRadius: '12px', border: '1px solid var(--sr-border, #E2E8F0)', bgcolor: 'var(--sr-surface, #FFFFFF)', overflow: 'hidden' }} elevation={0}>
              <Tabs
                value={activeTab}
                onChange={(_, val) => setActiveTab(val)}
                textColor="primary"
                indicatorColor="primary"
                sx={{
                  borderBottom: '1px solid var(--sr-border, #E2E8F0)',
                  '& .MuiTabs-indicator': { bgcolor: '#107487', height: 3 },
                  '& .MuiTab-root': {
                    textTransform: 'none',
                    fontWeight: 700,
                    fontSize: 13,
                    py: 1.5,
                    color: 'text.secondary',
                    '&.Mui-selected': { color: 'var(--sr-emerald)' }
                  }
                }}
              >
                <Tab icon={<PersonIcon fontSize="small" />} iconPosition="start" label="Personal Profile" />
                <Tab
                  icon={<KycIcon fontSize="small" />}
                  iconPosition="start"
                  label={
                    <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                      <span>CNIC & Driving License Vault</span>
                      {isKycVerified ? (
                        <Chip label="Verified ✓" size="small" sx={{ bgcolor: 'rgba(5, 150, 105, 0.12)', color: 'var(--sr-emerald)', fontWeight: 800, fontSize: 10, height: 18 }} />
                      ) : (
                        <Chip label="Verify" size="small" sx={{ bgcolor: 'rgba(217, 119, 6, 0.12)', color: 'var(--sr-accent-text)', fontWeight: 800, fontSize: 10, height: 18 }} />
                      )}
                    </Box>
                  }
                />
                <Tab icon={<SecurityIcon fontSize="small" />} iconPosition="start" label="Security & Password" />
              </Tabs>
            </Paper>

            {/* TAB 0: Personal Profile */}
            {activeTab === 0 && (
              <Paper className="settings-form settings-form-wrapper" sx={{ p: 4, borderRadius: '16px', border: '1px solid var(--sr-border, #E2E8F0)' }} elevation={0}>
                <form onSubmit={handleSubmit(onSubmit)}>
                  <Avatar
                    loggedUser={user}
                    user={user}
                    size="large"
                    readonly={false}
                    onBeforeUpload={onBeforeUpload}
                    onChange={onAvatarChange}
                    color="disabled"
                    className="avatar-ctn"
                  />
                  <FormControl fullWidth margin="dense">
                    <InputLabel className="required">{commonStrings.FULL_NAME}</InputLabel>
                    <Input {...register('fullName')} type="text" required autoComplete="off" />
                  </FormControl>
                  <FormControl fullWidth margin="dense">
                    <InputLabel className="required">{commonStrings.EMAIL}</InputLabel>
                    <Input {...register('email')} type="text" disabled />
                  </FormControl>
                  <FormControl fullWidth margin="dense" error={!!errors.phone}>
                    <InputLabel className="required">{commonStrings.PHONE}</InputLabel>
                    <Input
                      {...register('phone')}
                      type="text"
                      required
                      autoComplete="off"
                      onChange={() => {
                        if (errors.phone) {
                          clearErrors('phone')
                        }
                      }}
                    />
                    <FormHelperText>{errors.phone?.message || ''}</FormHelperText>
                  </FormControl>
                  <FormControl fullWidth margin="dense" error={!!errors.birthDate}>
                    <DatePicker
                      label={commonStrings.BIRTH_DATE}
                      variant="standard"
                      required
                      value={birthDate || undefined}
                      onChange={(date) => {
                        if (date) {
                          if (errors.birthDate) {
                            clearErrors('birthDate')
                          }
                          setValue('birthDate', date, { shouldValidate: true })
                        }
                      }}
                      language={user.language}
                    />
                    <FormHelperText>{errors.birthDate?.message || ''}</FormHelperText>
                  </FormControl>
                  <FormControl fullWidth margin="dense">
                    <InputLabel>{commonStrings.LOCATION}</InputLabel>
                    <Input {...register('location')} type="text" autoComplete="off" />
                  </FormControl>
                  <FormControl fullWidth margin="dense">
                    <InputLabel>{commonStrings.BIO}</InputLabel>
                    <Input {...register('bio')} type="text" autoComplete="off" />
                  </FormControl>

                  {/* Notification preference */}
                  <Box sx={{ mt: 2, mb: 1, p: 2, bgcolor: 'var(--sr-surface-raised, #F8FAFC)', borderRadius: '10px' }}>
                    <FormControlLabel
                      control={<Switch checked={enableEmailNotifications} onChange={handleEmailNotificationsChange} color="primary" />}
                      label={strings.SETTINGS_EMAIL_NOTIFICATIONS}
                    />
                  </Box>

                  <div className="buttons" style={{ marginTop: 24 }}>
                    <Button
                      type="submit"
                      variant="contained"
                      className="btn-primary"
                      disabled={isSubmitting}
                      sx={{ bgcolor: '#107487', '&:hover': { bgcolor: '#047857' }, fontWeight: 700, px: 3, textTransform: 'none', borderRadius: '8px' }}
                    >
                      {commonStrings.SAVE}
                    </Button>
                    <Button
                      variant="outlined"
                      color="primary"
                      onClick={(e) => {
                        e.preventDefault()
                        navigate('/')
                      }}
                      sx={{ textTransform: 'none', borderRadius: '8px', ml: 1 }}
                    >
                      {commonStrings.CANCEL}
                    </Button>
                  </div>
                </form>
              </Paper>
            )}

            {/* TAB 1: CNIC & Driving License KYC Vault */}
            {activeTab === 1 && (
              <Box sx={{ display: 'flex', flexDirection: 'column', gap: 3 }}>
                {/* Status Alert Banner */}
                <Box
                  sx={{
                    p: 2.5,
                    borderRadius: '12px',
                    bgcolor: isKycVerified ? 'rgba(5, 150, 105, 0.08)' : 'rgba(217, 119, 6, 0.08)',
                    border: `1px solid ${isKycVerified ? 'rgba(5, 150, 105, 0.25)' : 'rgba(217, 119, 6, 0.25)'}`,
                    display: 'flex',
                    alignItems: 'center',
                    gap: 2
                  }}
                >
                  {isKycVerified ? <VerifiedIcon sx={{ color: 'var(--sr-emerald)', fontSize: 28 }} /> : <WarningIcon sx={{ color: 'var(--sr-accent-text)', fontSize: 28 }} />}
                  <Box>
                    <Typography variant="subtitle2" sx={{ fontWeight: 800, color: isKycVerified ? 'var(--sr-emerald)' : 'var(--sr-accent-text)' }}>
                      {isKycVerified ? 'CNIC Identity & Self-Drive Verified' : 'KYC Verification In Progress'}
                    </Typography>
                    <Typography variant="caption" color="text.secondary">
                      {isKycVerified
                        ? 'Your Pakistani CNIC and Driving License are approved for instant key handover with zero blank cheques.'
                        : 'Submit your 13-digit Pakistani CNIC and license below for admin dispatch clearance.'}
                    </Typography>
                  </Box>
                </Box>

                {/* Form Card for CNIC & License Numbers */}
                <Paper className="settings-form settings-form-wrapper" sx={{ p: 4, borderRadius: '16px', border: '1px solid var(--sr-border, #E2E8F0)' }} elevation={0}>
                  <form onSubmit={handleSubmit(onSubmit)}>
                    <Typography variant="h6" sx={{ fontWeight: 700, mb: 2 }}>
                      Identification Numbers
                    </Typography>
                    <FormControl fullWidth margin="dense" error={!!errors.cnicNumber}>
                      <InputLabel>CNIC Number (12345-1234567-1)</InputLabel>
                      <Input {...register('cnicNumber')} type="text" autoComplete="off" />
                      <FormHelperText>{errors.cnicNumber?.message || `Current status: ${user.kycStatus || bookcarsTypes.KycStatus.Unverified}`}</FormHelperText>
                    </FormControl>
                    <FormControl fullWidth margin="dense" error={!!errors.drivingLicenseNumber} sx={{ mt: 2 }}>
                      <InputLabel>Driving License Number</InputLabel>
                      <Input {...register('drivingLicenseNumber')} type="text" autoComplete="off" />
                      <FormHelperText>{errors.drivingLicenseNumber?.message || 'Required for self-drive bookings.'}</FormHelperText>
                    </FormControl>

                    <Button
                      type="submit"
                      variant="contained"
                      className="btn-primary"
                      disabled={isSubmitting}
                      sx={{ mt: 3, bgcolor: '#107487', '&:hover': { bgcolor: '#047857' }, fontWeight: 700, textTransform: 'none', borderRadius: '8px' }}
                    >
                      Update Identity Numbers
                    </Button>
                  </form>
                </Paper>

                {/* Document Upload Dropzones */}
                <Paper className="settings-form settings-form-wrapper" sx={{ p: 4, borderRadius: '16px', border: '1px solid var(--sr-border, #E2E8F0)' }} elevation={0}>
                  <Typography variant="h6" sx={{ fontWeight: 700, mb: 1 }}>
                    {commonStrings.DRIVER_LICENSE} & Smart Card Upload
                  </Typography>
                  <Typography variant="caption" color="text.secondary" sx={{ display: 'block', mb: 2 }}>
                    Upload clear photos of the front and back of your official license card (JPEG or PNG).
                  </Typography>
                  <DriverLicense user={user} />
                </Paper>
              </Box>
            )}

            {/* TAB 2: Security & Password */}
            {activeTab === 2 && (
              <Paper className="settings-form settings-form-wrapper" sx={{ p: 4, borderRadius: '16px', border: '1px solid var(--sr-border, #E2E8F0)' }} elevation={0}>
                <Box sx={{ display: 'flex', alignItems: 'center', gap: 1.5, mb: 2 }}>
                  <KeyIcon sx={{ color: 'var(--sr-emerald)', fontSize: 24 }} />
                  <Typography variant="h6" sx={{ fontWeight: 700 }}>
                    Account Security & Credentials
                  </Typography>
                </Box>
                <Typography variant="body2" color="text.secondary" sx={{ mb: 3 }}>
                  Keep your account safe by updating your password regularly. Never share your password or OTP tokens with anyone.
                </Typography>

                <Box sx={{ p: 2.5, borderRadius: '10px', bgcolor: 'var(--sr-surface-raised, #F8FAFC)', border: '1px solid var(--sr-border, #E2E8F0)', mb: 3 }}>
                  <Typography variant="subtitle2" sx={{ fontWeight: 700, mb: 0.5 }}>
                    Change Master Password
                  </Typography>
                  <Typography variant="caption" color="text.secondary" sx={{ display: 'block', mb: 2 }}>
                    You will be asked to enter your current password and choose a strong new one.
                  </Typography>
                  <Button
                    variant="contained"
                    onClick={() => navigate('/change-password')}
                    sx={{
                      bgcolor: '#107487',
                      '&:hover': { bgcolor: '#047857' },
                      fontWeight: 700,
                      fontSize: 13,
                      textTransform: 'none',
                      borderRadius: '8px'
                    }}
                  >
                    Change Password
                  </Button>
                </Box>
              </Paper>
            )}
          </div>

          <Footer />
        </>
      )}
      {loading && <Backdrop text={commonStrings.PLEASE_WAIT} />}
    </Layout>
  )
}

export default Settings
